CREATE OR REPLACE FUNCTION rakeezx.apply_n58_empty_foundation(p_repair_id text, p_plan jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid:=auth.uid(); v_prior rakeezx.n58_foundation_repair_receipts%rowtype;
 v_fresh jsonb; v_expected jsonb; v_result jsonb; v_results jsonb:='[]'; v_year jsonb; v_index integer; v_term jsonb; v_preset text;
begin
 if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
 if p_repair_id is null or p_repair_id !~ '^[a-f0-9-]{36}$' or jsonb_typeof(p_plan) is distinct from 'object'
   or octet_length(p_plan::text)>32768 or p_plan->>'ownerId' is distinct from v_owner::text then raise exception 'N58_REPAIR_INVALID_PLAN'; end if;
 perform rakeezx.lock_student_lifecycle(v_owner);
 select * into v_prior from rakeezx.n58_foundation_repair_receipts where owner_id=v_owner and repair_id=p_repair_id;
 if found then
  if v_prior.plan is distinct from p_plan then raise exception 'N58_REPAIR_ID_REUSED'; end if;
  return v_prior.result; -- before rechecking later legitimate school additions
 end if;
 v_fresh:=rakeezx.review_n58_empty_foundation(p_plan->'request');
 if v_fresh is distinct from p_plan then raise exception 'N58_REPAIR_STALE_PLAN'; end if;
 v_preset:=p_plan->'request'->>'presetId';v_expected:=rakeezx.n58_repair_expected(v_preset);
 if jsonb_array_length(p_plan->'snapshot'->'years')=0 then
  v_result:=rakeezx.apply_sync_v2_mutation('years','y:1448-1449',p_repair_id||':year',p_repair_id,0,v_expected->'year','create',null);
  if v_result->>'outcome'<>'applied' then raise exception 'N58_REPAIR_YEAR_NOT_APPLIED'; end if;
  v_results:=v_results||jsonb_build_array(v_result);
 end if;
 for v_index in 1..2 loop
  if not exists(select 1 from rakeezx.terms where owner_id=v_owner and id='tm:y:1448-1449:'||v_index) then
   v_result:=rakeezx.apply_sync_v2_mutation('terms','tm:y:1448-1449:'||v_index,p_repair_id||':term'||v_index,p_repair_id,0,v_expected->'terms'->(v_index-1),'create',null);
   if v_result->>'outcome'<>'applied' then raise exception 'N58_REPAIR_TERM_NOT_APPLIED'; end if;
   v_results:=v_results||jsonb_build_array(v_result);
  end if;
 end loop;
 select to_jsonb(y) into v_year from rakeezx.years y where owner_id=v_owner and id='y:1448-1449';
 if v_year->>'calendar_preset_id' is distinct from v_preset then
  v_result:=rakeezx.apply_sync_v2_mutation('years','y:1448-1449',p_repair_id||':select',p_repair_id,(v_year->>'revision')::bigint,jsonb_build_object('calendar_preset_id',v_preset),'patch',null);
  if v_result->>'outcome'<>'applied' then raise exception 'N58_REPAIR_SELECTION_NOT_APPLIED'; end if;
  v_results:=v_results||jsonb_build_array(v_result);
 end if;
 v_result:=jsonb_build_object('protocol','N58_EMPTY_V1','ownerId',v_owner,'repairId',p_repair_id,
  'planDigest',encode(sha256(convert_to(p_plan::text,'UTF8')),'hex'),
  'canonical',rakeezx.n58_repair_snapshot(v_owner,v_preset),'mutationReceipts',v_results);
 insert into rakeezx.n58_foundation_repair_receipts(owner_id,repair_id,plan,result) values(v_owner,p_repair_id,p_plan,v_result);
 return v_result;
end $function$

CREATE OR REPLACE FUNCTION rakeezx.apply_reviewed_grade_import(p_mutation_id text, p_device_id text, p_batch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid:=auth.uid(); v_saved rakeezx.score_domain_receipts%rowtype;
  v_envelope jsonb; v_result jsonb; v_teaching rakeezx.teachings%rowtype;
  v_item rakeezx.items%rowtype; v_score rakeezx.scores%rowtype; v_cell jsonb; v_new jsonb;
  v_value numeric; v_max numeric; v_item_ids text[]; v_score_ids text[]:='{}'; v_id text;
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  if coalesce(length(p_mutation_id),0) not between 1 and 200 or coalesce(length(p_device_id),0) not between 1 and 200 or
    jsonb_typeof(p_batch) is distinct from 'object' or jsonb_typeof(p_batch->'cells') is distinct from 'array' or
    jsonb_typeof(p_batch->'newItems') is distinct from 'array' then
    raise exception using errcode='22023',message='Invalid reviewed batch'; end if;
  if jsonb_array_length(p_batch->'cells') not between 1 and 15000 or jsonb_array_length(p_batch->'newItems')>50 or
    (select count(distinct x->>'studentId') from jsonb_array_elements(p_batch->'cells') x)>300 or
    (select count(distinct x->>'itemId') from jsonb_array_elements(p_batch->'cells') x)>50 or
    (select count(distinct (x->>'studentId',x->>'itemId')) from jsonb_array_elements(p_batch->'cells') x)<>jsonb_array_length(p_batch->'cells') or
    (select count(distinct x->>'id') from jsonb_array_elements(p_batch->'newItems') x)<>jsonb_array_length(p_batch->'newItems') then
    raise exception using errcode='22023',message='Duplicate or oversized reviewed batch'; end if;
  -- Same ordering as existing lifecycle writes, then receipt and item locks.
  perform rakeezx.lock_student_lifecycle(v_owner);
  perform pg_advisory_xact_lock(hashtextextended(v_owner::text||':score-domain-receipt:'||p_mutation_id,0));
  v_envelope:=jsonb_build_object('protocol','N90_REVIEWED_V1','deviceId',p_device_id,'batch',p_batch);
  select * into v_saved from rakeezx.score_domain_receipts where owner_id=v_owner and mutation_id=p_mutation_id;
  if found then
    if v_saved.request_envelope is distinct from v_envelope then raise exception using errcode='22023',message='Grade mutation ID reused'; end if;
    return v_saved.result;
  end if;
  select * into v_teaching from rakeezx.teachings where owner_id=v_owner and id=p_batch->>'teachingId' and deleted_at is null for update;
  if v_teaching.id is null or v_teaching.revision is distinct from (p_batch->>'teachingRevision')::bigint or
    v_teaching.term_id is distinct from p_batch->>'termId' or not exists (
      select 1 from rakeezx.sections s join rakeezx.terms t on t.owner_id=s.owner_id and t.year_id=s.year_id
      join rakeezx.years y on y.owner_id=s.owner_id and y.id=s.year_id
      join rakeezx.subjects u on u.owner_id=s.owner_id and u.id=v_teaching.subject_id
      where s.owner_id=v_owner and s.id=v_teaching.section_id and t.id=v_teaching.term_id and s.deleted_at is null
        and t.deleted_at is null and y.deleted_at is null and u.deleted_at is null and s.status<>'archived' and t.status='active' and y.status='active') then
    raise exception using errcode='PT409',message='Teaching or current term changed'; end if;
  for v_new in select value from jsonb_array_elements(p_batch->'newItems') order by value->>'id' loop
    v_max:=(v_new->>'max')::numeric;
    if coalesce(length(v_new->>'id'),0) not between 1 and 200 or coalesce(length(btrim(v_new->>'name')),0) not between 1 and 50 or
      v_max is null or v_max::text in ('NaN','Infinity','-Infinity') or v_max<=0 or v_max>9999.99 or v_max<>round(v_max,2) or
      not exists(select 1 from jsonb_array_elements(p_batch->'cells') c where c->>'itemId'=v_new->>'id') then
      raise exception using errcode='22023',message='Invalid explicit new manual item'; end if;
    if exists(select 1 from rakeezx.items where owner_id=v_owner and id=v_new->>'id') then
      raise exception using errcode='PT409',message='New item identity already exists'; end if;
    insert into rakeezx.items(owner_id,id,teaching_id,name,max,"order",score_mode,auto,device_id)
      values(v_owner,v_new->>'id',v_teaching.id,btrim(v_new->>'name'),v_max,
        coalesce((select max("order")+1 from rakeezx.items where owner_id=v_owner and teaching_id=v_teaching.id),0),'direct',null,p_device_id);
  end loop;
  select array_agg(distinct x->>'itemId' order by x->>'itemId') into v_item_ids from jsonb_array_elements(p_batch->'cells') x;
  perform 1 from rakeezx.items where owner_id=v_owner and id=any(v_item_ids) order by id for update;
  for v_cell in select value from jsonb_array_elements(p_batch->'cells') order by value->>'itemId',value->>'studentId' loop
    select * into v_item from rakeezx.items where owner_id=v_owner and id=v_cell->>'itemId';
    v_value:=(v_cell->>'value')::numeric;
    if v_item.id is null or v_item.deleted_at is not null or v_item.teaching_id<>v_teaching.id or v_item.score_mode<>'direct' or v_item.auto is not null or
      v_item.max is distinct from (v_cell->>'max')::numeric or
      (not exists(select 1 from jsonb_array_elements(p_batch->'newItems') x where x->>'id'=v_item.id) and v_item.revision is distinct from (v_cell->>'itemRevision')::bigint) or
      v_value is null or v_value::text in ('NaN','Infinity','-Infinity') or v_value<0 or v_value>v_item.max or v_value<>round(v_value,2) then
      raise exception using errcode='PT409',message='Item or grade changed or invalid'; end if;
    if not exists(select 1 from rakeezx.students s join rakeezx.enrollments e on e.owner_id=s.owner_id and e.student_id=s.id
      where s.owner_id=v_owner and s.id=v_cell->>'studentId' and s.deleted_at is null and e.deleted_at is null and e.status='active' and e.section_id=v_teaching.section_id) then
      raise exception using errcode='42501',message='Student outside current enrollment'; end if;
    select * into v_score from rakeezx.scores where owner_id=v_owner and student_id=v_cell->>'studentId' and item_id=v_item.id for update;
    if v_score.deleted_at is not null or v_score.id is distinct from v_cell->>'scoreId' or
      coalesce(v_score.revision,0) is distinct from (v_cell->>'scoreRevision')::bigint or v_score.value is distinct from (v_cell->>'old')::numeric then
      raise exception using errcode='PT409',message='Score changed since review'; end if;
    if v_score.value is not null and v_score.value<>v_value and (p_batch->>'overwriteConfirmed') is distinct from 'true' then
      raise exception using errcode='22023',message='Explicit overwrite confirmation required'; end if;
    if v_score.id is null then
      v_id:='sc:'||(v_cell->>'studentId')||':'||v_item.id;
      insert into rakeezx.scores(owner_id,id,student_id,item_id,value,device_id)
        values(v_owner,v_id,v_cell->>'studentId',v_item.id,v_value,p_device_id);
    else
      v_id:=v_score.id;
      update rakeezx.scores set value=v_value,device_id=p_device_id where owner_id=v_owner and id=v_id;
    end if;
    v_score_ids:=array_append(v_score_ids,v_id);
  end loop;
  v_result:=jsonb_build_object('protocol','N90_REVIEWED_V1','mutationId',p_mutation_id,'teachingId',v_teaching.id,
    'items',(select coalesce(jsonb_agg(to_jsonb(i) order by id),'[]') from rakeezx.items i where owner_id=v_owner and id=any(v_item_ids)),
    'scores',(select coalesce(jsonb_agg(to_jsonb(s) order by id),'[]') from rakeezx.scores s where owner_id=v_owner and id=any(v_score_ids)),
    'score_subitems','[]'::jsonb,'score_subitem_completions','[]'::jsonb);
  insert into rakeezx.score_domain_receipts(owner_id,mutation_id,request_envelope,result) values(v_owner,p_mutation_id,v_envelope,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.apply_score_configuration_command(p_mutation_id text, p_device_id text, p_item_id text, p_expected_version bigint, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid:=auth.uid(); v_envelope jsonb; v_receipt rakeezx.score_domain_receipts%rowtype;
  v_item rakeezx.items%rowtype; v_mode text; v_distribution text; v_max numeric(6,2);
  v_definition jsonb; v_id text; v_name text; v_value numeric(6,2); v_order integer;
  v_start date; v_due date; v_late numeric; v_old rakeezx.score_subitems%rowtype;
  v_count integer; v_position integer:=0; v_total_cents bigint; v_each bigint;
  v_ids text[]:='{}'::text[]; v_student text; v_result jsonb; v_scores jsonb:='[]'::jsonb;
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  if coalesce(p_mutation_id,'')='' or char_length(p_mutation_id)>200 or
     coalesce(p_device_id,'')='' or char_length(p_device_id)>200 or
     coalesce(p_item_id,'')='' or p_expected_version is null or p_expected_version<1 or
     p_payload is null or pg_catalog.jsonb_typeof(p_payload)<>'object' or
     pg_catalog.jsonb_typeof(p_payload->'subitems')<>'array' then
    raise exception using errcode='22023',message='Invalid score configuration envelope';
  end if;
  v_envelope:=pg_catalog.jsonb_build_object('deviceId',p_device_id,'itemId',p_item_id,
    'expectedVersion',p_expected_version,'payload',p_payload);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    v_owner::text||':score-domain-receipt:'||p_mutation_id,0));
  select * into v_receipt from rakeezx.score_domain_receipts
    where owner_id=v_owner and mutation_id=p_mutation_id;
  if found then
    if v_receipt.request_envelope is distinct from v_envelope then
      raise exception using errcode='22023',message='Score mutation ID reused with different content';
    end if;
    return v_receipt.result;
  end if;
  select * into v_item from rakeezx.items where owner_id=v_owner and id=p_item_id
    and deleted_at is null for update;
  if not found or v_item.distribution_version<>p_expected_version then
    raise exception using errcode='40001',message='Score configuration revision changed';
  end if;
  v_mode:=p_payload->>'scoreMode';
  v_distribution:=p_payload->>'distributionMode';
  if (p_payload->>'max')::numeric is distinct from
      pg_catalog.round((p_payload->>'max')::numeric,2) then
    raise exception using errcode='22023',message='Score maximum requires two-decimal precision';
  end if;
  v_max:=(p_payload->>'max')::numeric(6,2);
  v_count:=pg_catalog.jsonb_array_length(p_payload->'subitems');
  if v_mode is null or v_mode not in ('direct','subitems') or v_max is null or v_max<=0 or
     (v_mode='subitems' and (v_distribution is null or v_distribution not in ('auto','manual') or v_count<1 or v_count>200)) or
     (v_mode='direct' and v_count<>0) then
    raise exception using errcode='22023',message='Invalid score configuration';
  end if;
  if v_item.score_mode='direct' and v_mode='subitems' and exists(
    select 1 from rakeezx.scores where owner_id=v_owner and item_id=p_item_id
      and deleted_at is null and value is not null
  ) and (p_payload->>'conversionStrategy') is distinct from 'retain-as-manual' then
    raise exception using errcode='22023',message='Direct scores require reviewed conversion';
  end if;
  perform pg_catalog.set_config('rakeezx.score_domain_write','on',true);
  if v_item.score_mode='direct' and v_mode='subitems' then
    update rakeezx.scores set manual_value=value,derived_value=0
      where owner_id=v_owner and item_id=p_item_id and deleted_at is null;
  end if;
  update rakeezx.items set max=v_max,score_mode=v_mode,
    distribution_mode=case when v_mode='subitems' then v_distribution else null end,
    portability_group_id=case when v_mode='subitems' then null else portability_group_id end,
    distribution_version=p_expected_version+1,device_id=p_device_id
    where owner_id=v_owner and id=p_item_id returning * into v_item;
  if v_mode='direct' then
    update rakeezx.scores set manual_value=null,derived_value=null,device_id=p_device_id
      where owner_id=v_owner and item_id=p_item_id and deleted_at is null;
  else
    v_total_cents:=pg_catalog.round(v_max*100)::bigint;
    v_each:=v_total_cents/v_count;
    for v_definition in select value from pg_catalog.jsonb_array_elements(p_payload->'subitems') loop
      v_position:=v_position+1;
      v_id:=v_definition->>'id'; v_name:=v_definition->>'name';
      if coalesce(v_id,'')='' or char_length(v_id)>240 or coalesce(v_name,'')='' or
         v_id=any(v_ids) or pg_catalog.jsonb_typeof(v_definition)<>'object' then
        raise exception using errcode='22023',message='Invalid or duplicate subitem identity';
      end if;
      v_ids:=pg_catalog.array_append(v_ids,v_id);
      v_order:=v_position-1;
      if v_distribution='auto' then
        v_value:=(case when v_position=v_count then v_total_cents-v_each*(v_count-1)
          else v_each end)::numeric/100;
      else
        if (v_definition->>'value')::numeric is distinct from
            pg_catalog.round((v_definition->>'value')::numeric,2) then
          raise exception using errcode='22023',message='Subitem value requires two-decimal precision';
        end if;
        v_value:=(v_definition->>'value')::numeric(6,2);
        if v_value is null or v_value<0 then
          raise exception using errcode='22023',message='Invalid manual subitem value';
        end if;
      end if;
      if exists(select 1 from rakeezx.score_subitems where owner_id=v_owner and id=v_id
        and (item_id<>p_item_id or deleted_at is not null)) then
        raise exception using errcode='22023',message='Subitem identity is unavailable';
      end if;
      select * into v_old from rakeezx.score_subitems where owner_id=v_owner and id=v_id;
      v_start:=case when v_definition ? 'startDate' then nullif(v_definition->>'startDate','')::date else v_old.start_date end;
      v_due:=case when v_definition ? 'dueDate' then nullif(v_definition->>'dueDate','')::date else v_old.due_date end;
      v_late:=case when v_definition ? 'latePoints' then nullif(v_definition->>'latePoints','')::numeric else v_old.late_points end;
      insert into rakeezx.score_subitems(owner_id,id,item_id,name,value,"order",distribution_version,start_date,due_date,late_points,device_id)
        values(v_owner,v_id,p_item_id,v_name,v_value,v_order,p_expected_version+1,v_start,v_due,v_late,p_device_id)
        on conflict(owner_id,id) do update set name=excluded.name,value=excluded.value,
          "order"=excluded."order",distribution_version=excluded.distribution_version,
          start_date=excluded.start_date,due_date=excluded.due_date,late_points=excluded.late_points,device_id=excluded.device_id;
    end loop;
    update rakeezx.score_subitems set deleted_at=pg_catalog.clock_timestamp(),device_id=p_device_id
      where owner_id=v_owner and item_id=p_item_id and deleted_at is null and not(id=any(v_ids));
    for v_student in
      select distinct student_id from rakeezx.scores
        where owner_id=v_owner and item_id=p_item_id and deleted_at is null
      union
      select distinct c.student_id from rakeezx.score_subitem_completions c
        join rakeezx.score_subitems d on d.owner_id=c.owner_id and d.id=c.subitem_id
        where c.owner_id=v_owner and d.item_id=p_item_id and c.checked and c.deleted_at is null
    loop
      v_scores:=v_scores||pg_catalog.jsonb_build_array(
        rakeezx.recompute_subitem_score(v_owner,p_item_id,v_student,p_device_id));
    end loop;
  end if;
  v_result:=pg_catalog.jsonb_build_object('mutationId',p_mutation_id,
    'item',pg_catalog.to_jsonb(v_item),'scores',v_scores,
    'subitems',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(d) order by d."order",d.id),'[]'::jsonb)
      from rakeezx.score_subitems d where d.owner_id=v_owner and d.item_id=p_item_id));
  insert into rakeezx.score_domain_receipts(owner_id,mutation_id,request_envelope,result)
    values(v_owner,p_mutation_id,v_envelope,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.apply_score_distribution_copy_command(p_mutation_id text, p_device_id text, p_source_item_id text, p_source_revision bigint, p_target_teaching_id text, p_new_item_id text, p_subitem_ids jsonb, p_conflict_choice text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid:=auth.uid(); v_envelope jsonb; v_receipt rakeezx.score_domain_receipts%rowtype;
  v_source rakeezx.items%rowtype; v_source_teaching rakeezx.teachings%rowtype;
  v_target rakeezx.teachings%rowtype; v_source_section rakeezx.sections%rowtype;
  v_target_section rakeezx.sections%rowtype; v_definition rakeezx.score_subitems%rowtype;
  v_mapping jsonb; v_new_subitem text; v_new_item rakeezx.items%rowtype;
  v_subitems jsonb; v_result jsonb; v_count integer;
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  if coalesce(p_mutation_id,'')='' or pg_catalog.char_length(p_mutation_id)>200 or
     coalesce(p_device_id,'')='' or coalesce(p_source_item_id,'')='' or
     coalesce(p_target_teaching_id,'')='' or coalesce(p_new_item_id,'')='' or
     p_source_revision is null or p_source_revision<1 or
     pg_catalog.jsonb_typeof(p_subitem_ids)<>'object' or
     coalesce(p_conflict_choice,'') not in ('missing','add') then
    raise exception using errcode='22023',message='Invalid distribution copy envelope';
  end if;
  v_envelope:=pg_catalog.jsonb_build_object('deviceId',p_device_id,'sourceItemId',p_source_item_id,
    'sourceRevision',p_source_revision,'targetTeachingId',p_target_teaching_id,
    'newItemId',p_new_item_id,'subitemIds',p_subitem_ids,'conflictChoice',p_conflict_choice);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    v_owner::text||':score-domain-receipt:'||p_mutation_id,0));
  select * into v_receipt from rakeezx.score_domain_receipts
    where owner_id=v_owner and mutation_id=p_mutation_id;
  if found then
    if v_receipt.request_envelope is distinct from v_envelope then
      raise exception using errcode='22023',message='Copy mutation ID reused with different content'; end if;
    return v_receipt.result;
  end if;
  select * into v_source from rakeezx.items where owner_id=v_owner and id=p_source_item_id
    and deleted_at is null for update;
  select * into v_target from rakeezx.teachings where owner_id=v_owner
    and id=p_target_teaching_id and deleted_at is null for update;
  if v_source.id is null or v_target.id is null or v_source.revision<>p_source_revision then
    raise exception using errcode='40001',message='Copy source or target is stale'; end if;
  select * into v_source_teaching from rakeezx.teachings where owner_id=v_owner
    and id=v_source.teaching_id and deleted_at is null;
  select * into v_source_section from rakeezx.sections where owner_id=v_owner
    and id=v_source_teaching.section_id and deleted_at is null;
  select * into v_target_section from rakeezx.sections where owner_id=v_owner
    and id=v_target.section_id and deleted_at is null;
  if v_source_teaching.id is null or v_source_section.id is null or v_target_section.id is null or
     v_source_section.status='archived' or v_target_section.status='archived' or
     v_source_teaching.id=v_target.id or v_source_section.id=v_target_section.id or
     v_source_teaching.subject_id<>v_target.subject_id or
     v_source_teaching.term_id<>v_target.term_id or
     v_source_section.year_id<>v_target_section.year_id or
     v_source_section.grade<>v_target_section.grade then
    raise exception using errcode='22023',message='Copy crosses an academic boundary'; end if;
  if exists(select 1 from rakeezx.items where owner_id=v_owner and id=p_new_item_id) then
    raise exception using errcode='22023',message='Destination item identity already exists'; end if;
  if p_conflict_choice='missing' and exists(select 1 from rakeezx.items where owner_id=v_owner
    and teaching_id=v_target.id and name=v_source.name and deleted_at is null) then
    raise exception using errcode='40001',message='Destination classification changed'; end if;
  select count(*) into v_count from rakeezx.score_subitems where owner_id=v_owner
    and item_id=v_source.id and deleted_at is null;
  if (v_source.score_mode='subitems' and
      (v_count=0 or (select count(*) from pg_catalog.jsonb_object_keys(p_subitem_ids))<>v_count)) or
     (v_source.score_mode<>'subitems' and
       (select count(*) from pg_catalog.jsonb_object_keys(p_subitem_ids))<>0) then
    raise exception using errcode='22023',message='Copy subitem mapping is incomplete'; end if;
  perform pg_catalog.set_config('rakeezx.score_domain_write','on',true);
  insert into rakeezx.items(owner_id,id,teaching_id,name,max,"order",auto,per_point,penalty,
    unit_id,lesson_id,score_mode,distribution_mode,distribution_version,
    distribution_origin_id,portability_group_id,device_id)
    values(v_owner,p_new_item_id,v_target.id,v_source.name,v_source.max,v_source."order",v_source.auto,
      v_source.per_point,v_source.penalty,v_source.unit_id,v_source.lesson_id,v_source.score_mode,
      v_source.distribution_mode,1,v_source.id,null,p_device_id)
    returning * into v_new_item;
  for v_definition in select * from rakeezx.score_subitems where owner_id=v_owner
      and item_id=v_source.id and deleted_at is null order by "order",id loop
    v_mapping:=p_subitem_ids->v_definition.id;
    v_new_subitem:=p_subitem_ids->>v_definition.id;
    if pg_catalog.jsonb_typeof(v_mapping)<>'string' or coalesce(v_new_subitem,'')='' or
       pg_catalog.char_length(v_new_subitem)>240 or exists(select 1 from rakeezx.score_subitems
         where owner_id=v_owner and id=v_new_subitem) then
      raise exception using errcode='22023',message='Copy subitem identity is invalid'; end if;
    insert into rakeezx.score_subitems(owner_id,id,item_id,name,value,"order",distribution_version,start_date,due_date,late_points,device_id)
      values(v_owner,v_new_subitem,p_new_item_id,v_definition.name,v_definition.value,
        v_definition."order",1,v_definition.start_date,v_definition.due_date,v_definition.late_points,p_device_id);
  end loop;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(d) order by d."order",d.id),'[]'::jsonb)
    into v_subitems from rakeezx.score_subitems d where d.owner_id=v_owner and d.item_id=p_new_item_id;
  v_result:=pg_catalog.jsonb_build_object('mutationId',p_mutation_id,
    'item',pg_catalog.to_jsonb(v_new_item),'subitems',v_subitems,'scores','[]'::jsonb);
  insert into rakeezx.score_domain_receipts(owner_id,mutation_id,request_envelope,result)
    values(v_owner,p_mutation_id,v_envelope,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.apply_score_distribution_plan(p_mutation_id text, p_device_id text, p_plan_id text, p_token text, p_confirmed boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid:=auth.uid(); v_saved rakeezx.score_distribution_plans%rowtype; v_receipt rakeezx.score_domain_receipts%rowtype;
  v_envelope jsonb; v_op jsonb; v_patch jsonb; v_entity text; v_id text; v_key text; v_sets text; v_columns text; v_values text;
  v_source text; v_targets text[]; v_accepted text[]; v_result jsonb; v_rows jsonb; v_ids text[]; v_affected bigint; v_now timestamptz:=clock_timestamp(); v_current jsonb;
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  if coalesce(p_mutation_id,'')='' or length(p_mutation_id)>200 or coalesce(p_device_id,'')='' or length(p_device_id)>200 or
    p_token is null or p_confirmed is null then raise exception using errcode='22023',message='Invalid distribution envelope'; end if;
  v_envelope:=jsonb_build_object('protocol','N73_D119_V2','deviceId',p_device_id,'planId',p_plan_id,'token',p_token,'confirmed',p_confirmed);
  perform pg_advisory_xact_lock(hashtextextended(v_owner::text||':score-domain-receipt:'||p_mutation_id,0));
  select * into v_receipt from rakeezx.score_domain_receipts where owner_id=v_owner and mutation_id=p_mutation_id;
  if found then
    if v_receipt.request_envelope is distinct from v_envelope then raise exception using errcode='22023',message='Distribution mutation ID reused'; end if;
    return v_receipt.result;
  end if;
  lock table rakeezx.items,rakeezx.score_subitems,rakeezx.score_subitem_completions,rakeezx.scores,
    rakeezx.teachings,rakeezx.sections,rakeezx.terms,rakeezx.years,rakeezx.subjects,rakeezx.students,
    rakeezx.enrollments,rakeezx.units,rakeezx.lessons,rakeezx.logs,rakeezx.attendance in share row exclusive mode;
  select * into v_saved from rakeezx.score_distribution_plans where owner_id=v_owner and id=p_plan_id;
  if not found then raise exception using errcode='42501',message='Distribution plan unavailable'; end if;
  if v_saved.fingerprint<>p_token or v_saved.created_at+interval '15 minutes'<clock_timestamp() then
    raise exception using errcode='PT409',message='Distribution plan expired or changed'; end if;
  if (v_saved.plan->>'requiresConfirmation')::boolean and not p_confirmed then
    raise exception using errcode='22023',message='Deliberate impact confirmation required'; end if;
  if jsonb_array_length(v_saved.plan->'targets')=0 then raise exception using errcode='22023',message='Resolve ambiguous targets before applying'; end if;
  v_source:=v_saved.request->>'source';
  select array_agg(x) into v_targets from jsonb_array_elements_text(v_saved.request->'targets') x;
  if v_saved.request->>'mode'='automatic-safe' and
    md5(jsonb_build_object('state',rakeezx.n73_distribution_state(v_source,v_targets),
      'request',v_saved.request,'operations',v_saved.plan->'operations')::text)<>v_saved.fingerprint then
    raise exception using errcode='PT409',message='Distribution changed since review'; end if;
  if v_saved.request->>'mode' in ('preserve-target','automatic-safe') then
    v_current:=rakeezx.n73_build_distribution(v_source,v_targets,
      array(select jsonb_array_elements_text(v_saved.request->'remove')),v_saved.request->>'mode');
    if md5(jsonb_build_object('state',rakeezx.n73_distribution_state(v_source,v_targets),
      'request',v_saved.request,'operations',v_current->'operations')::text)<>v_saved.fingerprint or
      v_current->'operations' is distinct from v_saved.plan->'operations' then
      raise exception using errcode='PT409',message='Distribution preservation mapping changed since review'; end if;
  elsif md5(rakeezx.n73_distribution_state(v_source,v_targets)::text)<>v_saved.fingerprint then
    raise exception using errcode='PT409',message='Distribution changed since review'; end if;
  perform set_config('rakeezx.score_domain_write','on',true);
  for v_op in select value from jsonb_array_elements(v_saved.plan->'operations') loop
    v_entity:=v_op->>'entity'; v_id:=v_op->>'id'; v_patch:=v_op->'patch';
    if v_patch->>'deleted_at'='__now__' then v_patch:=v_patch||jsonb_build_object('deleted_at',v_now); end if;
    v_patch:=v_patch||jsonb_build_object('device_id',p_device_id);
    if coalesce((v_op->>'create')::boolean,false) then
      v_patch:=v_patch||jsonb_build_object('owner_id',v_owner,'id',v_id);
      select string_agg(format('%I',k),',' order by k),string_agg(format('p.%I',k),',' order by k)
        into v_columns,v_values from jsonb_object_keys(v_patch) k;
      execute format('insert into rakeezx.%I(%s) select %s from jsonb_populate_record(null::rakeezx.%I,$1) p',v_entity,v_columns,v_values,v_entity) using v_patch;
    else
      select string_agg(format('%I=p.%I',k,k),',' order by k) into v_sets from jsonb_object_keys(v_patch) k;
      execute format('update rakeezx.%I t set %s from jsonb_populate_record(null::rakeezx.%I,$1) p where t.owner_id=$2 and t.id=$3 and t.deleted_at is null',v_entity,v_sets,v_entity)
        using v_patch,v_owner,v_id;
      get diagnostics v_affected=row_count;
      if v_affected<>1 then raise exception using errcode='PT409',message='Distribution operation unavailable'; end if;
    end if;
  end loop;
  v_result:=jsonb_build_object('mutationId',p_mutation_id,'planId',p_plan_id,'protocol','N73_D119_V2',
    'changedCount',v_saved.plan->'changedCount','excludedTargets',v_saved.plan->'excludedTargets');
  select array_agg(x->>'teachingId') into v_accepted from jsonb_array_elements(v_saved.plan->'targets') x;
  -- Full accepted-target canonical scope includes compatible unchanged scores
  -- and completions as well as tombstones. It never contains source grades.
  v_result:=v_result||jsonb_build_object(
    'items',(select coalesce(jsonb_agg(to_jsonb(i) order by i.id),'[]') from rakeezx.items i where owner_id=v_owner and teaching_id=any(v_accepted)),
    'score_subitems',(select coalesce(jsonb_agg(to_jsonb(d) order by d.id),'[]') from rakeezx.score_subitems d join rakeezx.items i
      on i.owner_id=d.owner_id and i.id=d.item_id where d.owner_id=v_owner and i.teaching_id=any(v_accepted)),
    'score_subitem_completions',(select coalesce(jsonb_agg(to_jsonb(c) order by c.id),'[]') from rakeezx.score_subitem_completions c
      join rakeezx.score_subitems d on d.owner_id=c.owner_id and d.id=c.subitem_id join rakeezx.items i on i.owner_id=d.owner_id and i.id=d.item_id
      where c.owner_id=v_owner and i.teaching_id=any(v_accepted)),
    'scores',(select coalesce(jsonb_agg(to_jsonb(s) order by s.id),'[]') from rakeezx.scores s join rakeezx.items i
      on i.owner_id=s.owner_id and i.id=s.item_id where s.owner_id=v_owner and i.teaching_id=any(v_accepted))
  );
  insert into rakeezx.score_domain_receipts(owner_id,mutation_id,request_envelope,result) values(v_owner,p_mutation_id,v_envelope,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.apply_score_subitem_command(p_mutation_id text, p_device_id text, p_command text, p_item_id text, p_student_id text, p_subitem_id text DEFAULT NULL::text, p_checked boolean DEFAULT NULL::boolean, p_manual_value numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid:=auth.uid(); v_envelope jsonb; v_receipt rakeezx.score_domain_receipts%rowtype;
  v_item rakeezx.items%rowtype; v_completion rakeezx.score_subitem_completions%rowtype;
  v_score jsonb; v_result jsonb;
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  if coalesce(p_mutation_id,'')='' or char_length(p_mutation_id)>200 or
     coalesce(p_device_id,'')='' or char_length(p_device_id)>200 or
     p_command not in ('set_completion','set_manual') or
     coalesce(p_item_id,'')='' or coalesce(p_student_id,'')='' or
     (p_command='set_completion' and (p_subitem_id is null or p_checked is null)) or
     (p_command='set_manual' and (p_subitem_id is not null or p_checked is not null)) or
     (p_manual_value is not null and (p_manual_value<0 or p_manual_value>9999.99 or
       p_manual_value<>pg_catalog.round(p_manual_value,2))) then
    raise exception using errcode='22023',message='Invalid score domain command';
  end if;
  v_envelope:=pg_catalog.jsonb_build_object('deviceId',p_device_id,'command',p_command,
    'itemId',p_item_id,'studentId',p_student_id,'subitemId',p_subitem_id,
    'checked',p_checked,'manualValue',p_manual_value);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    v_owner::text||':score-domain-receipt:'||p_mutation_id,0));
  select * into v_receipt from rakeezx.score_domain_receipts
    where owner_id=v_owner and mutation_id=p_mutation_id;
  if found then
    if v_receipt.request_envelope is distinct from v_envelope then
      raise exception using errcode='22023',message='Score mutation ID reused with different content';
    end if;
    return v_receipt.result;
  end if;
  -- The item row serializes completion, manual and definition changes across devices.
  select * into v_item from rakeezx.items where owner_id=v_owner and id=p_item_id
    and deleted_at is null for update;
  if not found or v_item.score_mode<>'subitems' or not exists(
    select 1 from rakeezx.students where owner_id=v_owner and id=p_student_id and deleted_at is null
  ) then raise exception using errcode='22023',message='Score item or student unavailable'; end if;
  perform pg_catalog.set_config('rakeezx.score_domain_write','on',true);
  if p_command='set_completion' then
    if not exists(select 1 from rakeezx.score_subitems where owner_id=v_owner and id=p_subitem_id
      and item_id=p_item_id and deleted_at is null) then
      raise exception using errcode='22023',message='Subitem unavailable';
    end if;
    insert into rakeezx.score_subitem_completions(owner_id,id,student_id,subitem_id,checked,completion_state,device_id)
      values(v_owner,'ssc:'||p_student_id||':'||p_subitem_id,p_student_id,p_subitem_id,p_checked,case when p_checked then 'regular' else null end,p_device_id)
      on conflict(owner_id,id) do update set checked=excluded.checked,completion_state=excluded.completion_state,device_id=excluded.device_id
        where rakeezx.score_subitem_completions.deleted_at is null
      returning * into v_completion;
    if not found then raise exception using errcode='22023',message='Deleted completion cannot be resurrected'; end if;
  else
    -- The requested amount is provisional until the authoritative projection clamps it.
    insert into rakeezx.scores(owner_id,id,student_id,item_id,manual_value,device_id)
      values(v_owner,'sc:'||p_student_id||':'||p_item_id,p_student_id,p_item_id,p_manual_value,p_device_id)
      on conflict(owner_id,id) do update set manual_value=excluded.manual_value,device_id=excluded.device_id;
  end if;
  v_score:=rakeezx.recompute_subitem_score(v_owner,p_item_id,p_student_id,p_device_id);
  v_result:=pg_catalog.jsonb_build_object('mutationId',p_mutation_id,'itemId',p_item_id,
    'studentId',p_student_id,'score',v_score,'completion',
    case when p_command='set_completion' then pg_catalog.to_jsonb(v_completion) else null end);
  insert into rakeezx.score_domain_receipts(owner_id,mutation_id,request_envelope,result)
    values(v_owner,p_mutation_id,v_envelope,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.apply_score_subitem_command_n94(p_mutation_id text, p_device_id text, p_command text, p_item_id text, p_student_id text, p_subitem_id text DEFAULT NULL::text, p_completion_state text DEFAULT NULL::text, p_manual_value numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid:=auth.uid(); v_envelope jsonb; v_receipt rakeezx.score_domain_receipts%rowtype;
  v_item rakeezx.items%rowtype; v_completion rakeezx.score_subitem_completions%rowtype;
  v_score jsonb; v_result jsonb;
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  if coalesce(p_mutation_id,'')='' or char_length(p_mutation_id)>200 or
     coalesce(p_device_id,'')='' or char_length(p_device_id)>200 or
     p_command is null or p_command not in ('set_completion','set_manual') or
     coalesce(p_item_id,'')='' or coalesce(p_student_id,'')='' or
     (p_command='set_completion' and (p_subitem_id is null or (p_completion_state is not null and p_completion_state not in ('regular','late')))) or
     (p_command='set_manual' and (p_subitem_id is not null or p_completion_state is not null)) or
     (p_manual_value is not null and (p_manual_value<0 or p_manual_value>9999.99 or
       p_manual_value<>pg_catalog.round(p_manual_value,2))) then
    raise exception using errcode='22023',message='Invalid score domain command';
  end if;
  v_envelope:=pg_catalog.jsonb_build_object('deviceId',p_device_id,'command',p_command,
    'itemId',p_item_id,'studentId',p_student_id,'subitemId',p_subitem_id,
    'completionState',p_completion_state,'manualValue',p_manual_value);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    v_owner::text||':score-domain-receipt:'||p_mutation_id,0));
  select * into v_receipt from rakeezx.score_domain_receipts
    where owner_id=v_owner and mutation_id=p_mutation_id;
  if found then
    if v_receipt.request_envelope is distinct from v_envelope then
      raise exception using errcode='22023',message='Score mutation ID reused with different content';
    end if;
    return v_receipt.result;
  end if;
  -- The item row serializes completion, manual and definition changes across devices.
  select * into v_item from rakeezx.items where owner_id=v_owner and id=p_item_id
    and deleted_at is null for update;
  if not found or v_item.score_mode<>'subitems' or not exists(
    select 1 from rakeezx.students where owner_id=v_owner and id=p_student_id and deleted_at is null
  ) then raise exception using errcode='22023',message='Score item or student unavailable'; end if;
  perform pg_catalog.set_config('rakeezx.score_domain_write','on',true);
  if p_command='set_completion' then
    if not exists(select 1 from rakeezx.score_subitems where owner_id=v_owner and id=p_subitem_id
      and item_id=p_item_id and deleted_at is null) then
      raise exception using errcode='22023',message='Subitem unavailable';
    end if;
    insert into rakeezx.score_subitem_completions(owner_id,id,student_id,subitem_id,checked,completion_state,device_id)
      values(v_owner,'ssc:'||p_student_id||':'||p_subitem_id,p_student_id,p_subitem_id,p_completion_state is not null,p_completion_state,p_device_id)
      on conflict(owner_id,id) do update set checked=excluded.checked,completion_state=excluded.completion_state,device_id=excluded.device_id
        where rakeezx.score_subitem_completions.deleted_at is null
      returning * into v_completion;
    if not found then raise exception using errcode='22023',message='Deleted completion cannot be resurrected'; end if;
  else
    -- The requested amount is provisional until the authoritative projection clamps it.
    insert into rakeezx.scores(owner_id,id,student_id,item_id,manual_value,device_id)
      values(v_owner,'sc:'||p_student_id||':'||p_item_id,p_student_id,p_item_id,p_manual_value,p_device_id)
      on conflict(owner_id,id) do update set manual_value=excluded.manual_value,device_id=excluded.device_id;
  end if;
  v_score:=rakeezx.recompute_subitem_score(v_owner,p_item_id,p_student_id,p_device_id);
  v_result:=pg_catalog.jsonb_build_object('mutationId',p_mutation_id,'itemId',p_item_id,
    'studentId',p_student_id,'score',v_score,'completion',
    case when p_command='set_completion' then pg_catalog.to_jsonb(v_completion) else null end);
  insert into rakeezx.score_domain_receipts(owner_id,mutation_id,request_envelope,result)
    values(v_owner,p_mutation_id,v_envelope,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.apply_student_lifecycle_command(p_mutation_id text, p_device_id text, p_command text, p_payload jsonb, p_client_updated_at bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid:=auth.uid(); v_student text:=p_payload->>'studentId';
  v_source text:=p_payload->>'sourceEnrollmentId';
  v_expected bigint:=nullif(p_payload->>'sourceRevision','')::bigint;
  v_s rakeezx.students%rowtype; v_e rakeezx.enrollments%rowtype; v_previous rakeezx.student_lifecycle_receipts%rowtype;
  v_envelope jsonb; v_result jsonb; v_rows jsonb; v_sections text[]:='{}';
  v_outcome text:='applied'; v_code text; v_reason text; v_plan jsonb;
  v_date date;
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  if coalesce(p_mutation_id,'')='' or char_length(p_mutation_id)>200 or coalesce(p_device_id,'')='' or char_length(p_device_id)>200 or
    coalesce(v_student,'')='' or p_command is null or p_command not in ('delete_pristine','end_enrollment') or
    jsonb_typeof(p_payload) is distinct from 'object' then
    raise exception using errcode='22023',message='Invalid student lifecycle command'; end if;
  if p_payload ? 'date' then raise exception using errcode='22023',message='IMMEDIATE_ONLY'; end if;
  v_envelope:=jsonb_build_object('mutationId',p_mutation_id,'deviceId',p_device_id,'command',p_command,
    'payload',p_payload,'clientUpdatedAt',p_client_updated_at);
  perform rakeezx.lock_student_lifecycle(v_owner);
  v_date:=rakeezx.student_lifecycle_date(clock_timestamp());
  select * into v_previous from rakeezx.student_lifecycle_receipts where owner_id=v_owner and mutation_id=p_mutation_id;
  if found then
    if v_previous.request_envelope is distinct from v_envelope then
      raise exception using errcode='22023',message='Mutation ID reused with different student lifecycle request'; end if;
    return v_previous.result;
  end if;
  -- Existing enrollment RPCs use this additional student lock as well.
  perform pg_advisory_xact_lock(hashtextextended(v_owner::text||':student:'||v_student,0));
  select * into v_s from rakeezx.students where owner_id=v_owner and id=v_student for update;
  if not found then v_outcome:='rejected'; v_code:='STUDENT_NOT_FOUND';
  elsif v_s.deleted_at is not null then
    v_outcome:=case when p_command='delete_pristine' then 'already_deleted' else 'rejected' end;
    v_code:='STUDENT_TOMBSTONED';
  elsif p_command='delete_pristine' then
    v_reason:=rakeezx.pristine_student_blocker(v_owner,v_student);
    if v_reason is not null then v_outcome:='protected'; v_code:='NOT_PRISTINE';
    else
      select coalesce(array_agg(section_id),'{}') into v_sections from rakeezx.enrollments where owner_id=v_owner and student_id=v_student;
      perform set_config('rakeezx.pristine_student_delete','on',true);
      update rakeezx.enrollments set deleted_at=clock_timestamp(),client_updated_at=p_client_updated_at,device_id=p_device_id
        where owner_id=v_owner and student_id=v_student and deleted_at is null;
      update rakeezx.students set deleted_at=clock_timestamp(),client_updated_at=p_client_updated_at,device_id=p_device_id
        where owner_id=v_owner and id=v_student returning * into v_s;
      perform set_config('rakeezx.pristine_student_delete','off',true);
    end if;
  elsif p_command='end_enrollment' then
    if coalesce(v_source,'')='' or v_expected is null then
      raise exception using errcode='22023',message='Exact source enrollment and revision required'; end if;
    select * into v_e from rakeezx.enrollments where owner_id=v_owner and id=v_source and student_id=v_student for update;
    v_code:=rakeezx.student_removal_source_blocker(v_owner,v_student,v_source,v_expected);
    if v_code='STALE_SOURCE_ENROLLMENT' then
      v_outcome:='rejected';
    elsif v_code='ARCHIVED_ENROLLMENT' then
      v_outcome:='protected';
    else
      v_sections:=array[v_e.section_id];
      update rakeezx.enrollments set status='withdrawn',end_date=v_date,transfer_note=coalesce(p_payload->>'note',''),
        client_updated_at=p_client_updated_at,device_id=p_device_id where owner_id=v_owner and id=v_source;
      if not exists(select 1 from rakeezx.enrollments where owner_id=v_owner and student_id=v_student and status='active' and deleted_at is null) then
        update rakeezx.students set status='withdrawn',client_updated_at=p_client_updated_at,device_id=p_device_id
          where owner_id=v_owner and id=v_student returning * into v_s;
      end if;
    end if;
  end if;
  if cardinality(v_sections)>0 then
    select coalesce(jsonb_agg(jsonb_build_object('id',id,'roll',roll)),'[]') into v_plan from
      (select id,row_number() over(partition by section_id order by roll_no nulls last,id) roll from rakeezx.enrollments
        where owner_id=v_owner and section_id=any(v_sections) and status='active' and deleted_at is null) p;
    update rakeezx.enrollments set roll_no=null where owner_id=v_owner and section_id=any(v_sections) and status='active' and deleted_at is null;
    update rakeezx.enrollments e set roll_no=p.roll,client_updated_at=p_client_updated_at,device_id=p_device_id
      from jsonb_to_recordset(v_plan) as p(id text,roll integer) where e.owner_id=v_owner and e.id=p.id;
  end if;
  select coalesce(jsonb_agg(to_jsonb(e) order by e.id),'[]') into v_rows from rakeezx.enrollments e
    where owner_id=v_owner and (student_id=v_student or section_id=any(v_sections));
  v_result:=jsonb_build_object('mutationId',p_mutation_id,'command',p_command,'outcome',v_outcome,
    'code',v_code,'reason',v_reason,'student',case when v_s.id is null then null else to_jsonb(v_s) end,'enrollments',v_rows);
  insert into rakeezx.student_lifecycle_receipts(owner_id,mutation_id,student_id,request_envelope,result)
    values(v_owner,p_mutation_id,v_student,v_envelope,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.apply_sync_v2_attendance_command_before_student_0029(p_mutation_id text, p_device_id text, p_attendance_id text, p_session_id text, p_student_id text, p_base_revision bigint, p_patch jsonb, p_client_updated_at bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid := auth.uid();
  v_receipt rakeezx.sync_mutation_receipts%rowtype;
  v_session rakeezx.sessions%rowtype;
  v_teaching rakeezx.teachings%rowtype;
  v_snapshot rakeezx.session_roster_snapshots%rowtype;
  v_attendance rakeezx.attendance%rowtype;
  v_envelope jsonb;
  v_members jsonb;
  v_requested_groups text[] := array[]::text[];
  v_applied_groups text[] := array[]::text[];
  v_conflicted_groups text[] := array[]::text[];
  v_field text;
  v_revision bigint;
  v_field_revisions jsonb;
  v_outcome text;
  v_result jsonb;
  v_snapshot_json jsonb;
  v_attendance_json jsonb;
begin
  if v_owner is null then raise exception using errcode = '42501', message = 'Authentication required'; end if;
  if coalesce(p_mutation_id, '') = '' or coalesce(p_device_id, '') = '' or
      coalesce(p_attendance_id, '') = '' or coalesce(p_session_id, '') = '' or
      coalesce(p_student_id, '') = '' or p_base_revision is null or p_base_revision < 0 or
      p_patch is null or pg_catalog.jsonb_typeof(p_patch) <> 'object' then
    raise exception using errcode = '22023', message = 'Invalid Sync V2 attendance command';
  end if;
  for v_field in select pg_catalog.jsonb_object_keys(p_patch)
  loop
    if v_field not in ('status', 'note') then
      raise exception using errcode = '22023', message = 'Attendance field is not allowed: ' || v_field;
    end if;
    v_requested_groups := array_append(v_requested_groups, v_field);
  end loop;
  if not ('status' = any(v_requested_groups)) and p_base_revision = 0 then
    raise exception using errcode = '22023', message = 'New attendance requires status';
  end if;
  v_envelope := pg_catalog.jsonb_build_object(
    'mutationId', p_mutation_id, 'deviceId', p_device_id, 'attendanceId', p_attendance_id,
    'sessionId', p_session_id, 'studentId', p_student_id, 'baseRevision', p_base_revision,
    'patch', p_patch, 'clientUpdatedAt', p_client_updated_at
  );
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text || ':sync-v2:' || p_mutation_id, 0));
  select * into v_receipt from rakeezx.sync_mutation_receipts where owner_id = v_owner and mutation_id = p_mutation_id;
  if found then
    if v_receipt.request_envelope is distinct from v_envelope then
      raise exception using errcode = '22023', message = 'Mutation ID was reused with a different request';
    end if;
    return v_receipt.result;
  end if;

  -- Serialize all first-attendance attempts for this historical session.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text || ':session-roster:' || p_session_id, 0));
  select * into v_session from rakeezx.sessions where owner_id = v_owner and id = p_session_id and deleted_at is null for update;
  if not found or v_session.status in ('cancelled', 'cancelled_holiday') then
    raise exception using errcode = '22023', message = 'Attendance session is unavailable';
  end if;
  select * into v_teaching from rakeezx.teachings where owner_id = v_owner and id = v_session.teaching_id and deleted_at is null for update;
  if not found then raise exception using errcode = '22023', message = 'Attendance teaching is unavailable'; end if;
  perform 1 from rakeezx.students where owner_id = v_owner and id = p_student_id and deleted_at is null for update;
  if not found then raise exception using errcode = '22023', message = 'Attendance student is unavailable'; end if;

  select * into v_snapshot from rakeezx.session_roster_snapshots
    where owner_id = v_owner and session_id = p_session_id and deleted_at is null for update;
  if not found then
    -- Existing legacy records are intentionally not used to synthesize a
    -- historical snapshot. Existing rows can still be edited below.
    if not exists (select 1 from rakeezx.attendance where owner_id = v_owner and session_id = p_session_id and deleted_at is null) then
      select coalesce(jsonb_agg(jsonb_build_object('studentId', e.student_id, 'rollNo', e.roll_no)
        order by e.roll_no nulls last, s.name, e.student_id), '[]'::jsonb)
        into v_members
      from rakeezx.enrollments e
      join rakeezx.students s on s.owner_id = e.owner_id and s.id = e.student_id and s.deleted_at is null
      where e.owner_id = v_owner and e.section_id = v_teaching.section_id and e.status = 'active' and e.deleted_at is null;
      perform set_config('rakeezx.sync_v2_attendance_snapshot', 'on', true);
      insert into rakeezx.session_roster_snapshots (owner_id, id, session_id, teaching_id, section_id, captured_at, members, state, client_updated_at, device_id)
      values (v_owner, 'srs:' || p_session_id, p_session_id, v_session.teaching_id, v_teaching.section_id,
        pg_catalog.clock_timestamp(), v_members, 'complete', p_client_updated_at, p_device_id)
      returning * into v_snapshot;
    end if;
  end if;

  select * into v_attendance from rakeezx.attendance
    where owner_id = v_owner and student_id = p_student_id and session_id = p_session_id for update;
  if v_attendance.id is null then
    if v_snapshot.id is null then
      raise exception using errcode = '22023', message = 'Legacy session membership is unresolved';
    end if;
    if not (v_snapshot.members @> jsonb_build_array(jsonb_build_object('studentId', p_student_id))) then
      raise exception using errcode = '22023', message = 'Student is outside the immutable session roster';
    end if;
    insert into rakeezx.attendance (owner_id, id, student_id, session_id, teaching_id, date, status, note, client_updated_at, device_id)
    values (v_owner, p_attendance_id, p_student_id, p_session_id, v_session.teaching_id, v_session.date,
      p_patch ->> 'status', coalesce(p_patch ->> 'note', ''), p_client_updated_at, p_device_id)
    returning * into v_attendance;
    v_applied_groups := v_requested_groups;
    v_outcome := 'applied';
  else
    v_revision := v_attendance.revision;
    if p_base_revision > v_revision then
      raise exception using errcode = '22023', message = 'Attendance base revision is ahead of the server';
    end if;
    if v_attendance.deleted_at is not null then
      v_outcome := 'tombstoned';
      v_conflicted_groups := array['__deleted__'];
    else
      v_field_revisions := v_attendance.field_revisions;
      foreach v_field in array v_requested_groups
      loop
        if coalesce((v_field_revisions ->> v_field)::bigint, 1) > p_base_revision then
          v_conflicted_groups := array_append(v_conflicted_groups, v_field);
        else
          v_applied_groups := array_append(v_applied_groups, v_field);
        end if;
      end loop;
      if 'status' = any(v_applied_groups) or 'note' = any(v_applied_groups) then
        update rakeezx.attendance set
          status = case when 'status' = any(v_applied_groups) then p_patch ->> 'status' else status end,
          note = case when 'note' = any(v_applied_groups) then p_patch ->> 'note' else note end,
          client_updated_at = p_client_updated_at, device_id = p_device_id
          where owner_id = v_owner and id = v_attendance.id
          returning * into v_attendance;
      end if;
      if cardinality(v_conflicted_groups) = 0 then v_outcome := 'applied';
      elsif cardinality(v_applied_groups) > 0 then v_outcome := 'applied_with_conflicts';
      else v_outcome := 'conflict';
      end if;
    end if;
  end if;

  if v_session.status = 'scheduled' and v_outcome in ('applied', 'applied_with_conflicts') then
    update rakeezx.sessions set status = 'held', client_updated_at = p_client_updated_at, device_id = p_device_id
      where owner_id = v_owner and id = p_session_id;
  end if;
  select pg_catalog.to_jsonb(t) into v_snapshot_json from rakeezx.session_roster_snapshots t
    where t.owner_id = v_owner and t.id = v_snapshot.id;
  select pg_catalog.to_jsonb(t) into v_attendance_json from rakeezx.attendance t
    where t.owner_id = v_owner and t.id = v_attendance.id;
  v_result := jsonb_build_object('mutationId', p_mutation_id, 'outcome', v_outcome,
    'appliedGroups', to_jsonb(v_applied_groups), 'conflictedGroups', to_jsonb(v_conflicted_groups),
    'snapshot', v_snapshot_json, 'attendance', v_attendance_json);
  insert into rakeezx.sync_mutation_receipts (owner_id, mutation_id, entity, record_id, device_id, base_revision, operation,
    client_updated_at, request_patch, request_envelope, outcome, applied_groups, conflicted_groups, result_revision, canonical, result)
  values (v_owner, p_mutation_id, 'attendance', p_attendance_id, p_device_id, p_base_revision, 'attendance',
    p_client_updated_at, p_patch, v_envelope, v_outcome, v_applied_groups, v_conflicted_groups,
    v_attendance.revision, v_attendance_json, v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.apply_sync_v2_class_goal_reward_command_before_student_0029(p_mutation_id text, p_device_id text, p_goal_id text, p_run_id text, p_client_updated_at bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid:=auth.uid(); v_receipt rakeezx.sync_mutation_receipts%rowtype; v_goal rakeezx.class_goals%rowtype;
  v_teaching rakeezx.teachings%rowtype; v_section rakeezx.sections%rowtype; v_term rakeezx.terms%rowtype;
  v_envelope jsonb; v_result jsonb; v_logs jsonb; v_now timestamptz:=clock_timestamp(); v_student text;
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  if coalesce(p_mutation_id,'')='' or coalesce(p_device_id,'')='' or coalesce(p_goal_id,'')='' or coalesce(p_run_id,'')='' then
    raise exception using errcode='22023',message='Invalid goal reward envelope';
  end if;
  v_envelope:=jsonb_build_object('mutationId',p_mutation_id,'deviceId',p_device_id,'goalId',p_goal_id,'runId',p_run_id,'clientUpdatedAt',p_client_updated_at);
  perform pg_advisory_xact_lock(hashtextextended(v_owner::text||':goal-reward:'||p_goal_id||':'||p_run_id,0));
  select * into v_receipt from rakeezx.sync_mutation_receipts where owner_id=v_owner and mutation_id=p_mutation_id;
  if found then
    if v_receipt.request_envelope is distinct from v_envelope then raise exception using errcode='22023',message='Mutation ID reused with different goal reward'; end if;
    return v_receipt.result;
  end if;
  select * into v_goal from rakeezx.class_goals where owner_id=v_owner and id=p_goal_id and deleted_at is null for update;
  if not found or v_goal.run_id<>p_run_id then raise exception using errcode='22023',message='Goal run is no longer current'; end if;
  select * into v_teaching from rakeezx.teachings where owner_id=v_owner and id=v_goal.teaching_id and deleted_at is null;
  select * into v_section from rakeezx.sections where owner_id=v_owner and id=v_teaching.section_id and deleted_at is null;
  select * into v_term from rakeezx.terms where owner_id=v_owner and id=v_teaching.term_id and deleted_at is null;
  if v_section.status<>'active' or v_term.status='closed' then raise exception using errcode='22023',message='Goal teaching is read-only'; end if;

  -- A different-device retry after completion returns the same deterministic rows.
  if v_goal.state='active' then
    if v_goal.session_id is not null and exists(select 1 from rakeezx.attendance a where a.owner_id=v_owner and a.session_id=v_goal.session_id and a.deleted_at is null)
       and not exists(select 1 from rakeezx.session_roster_snapshots s where s.owner_id=v_owner and s.session_id=v_goal.session_id and s.state='complete' and s.deleted_at is null) then
      raise exception using errcode='22023',message='Legacy session membership is unresolved';
    end if;
    perform set_config('rakeezx.class_goal_reward','on',true);
    for v_student in
      with members as (
        select e.student_id from rakeezx.enrollments e where v_goal.session_id is null and e.owner_id=v_owner and e.section_id=v_teaching.section_id and e.status='active' and e.deleted_at is null
        union
        select coalesce(member->>'studentId',member->>'id') from rakeezx.session_roster_snapshots s cross join lateral jsonb_array_elements(s.members) member
          where v_goal.session_id is not null and s.owner_id=v_owner and s.session_id=v_goal.session_id and s.state='complete' and s.deleted_at is null
        union
        select e.student_id from rakeezx.enrollments e where v_goal.session_id is not null and e.owner_id=v_owner and e.section_id=v_teaching.section_id and e.status='active' and e.deleted_at is null
          and not exists(select 1 from rakeezx.session_roster_snapshots s where s.owner_id=v_owner and s.session_id=v_goal.session_id and s.state='complete' and s.deleted_at is null)
      )
      select distinct m.student_id from members m join rakeezx.students st on st.owner_id=v_owner and st.id=m.student_id and st.deleted_at is null
      where not exists(select 1 from rakeezx.attendance a where v_goal.session_id is not null and a.owner_id=v_owner and a.session_id=v_goal.session_id and a.student_id=m.student_id and a.status in ('absent','excused') and a.deleted_at is null)
      order by m.student_id
    loop
      insert into rakeezx.logs(id,owner_id,student_id,teaching_id,session_id,date,kind,delta,tag,note,client_updated_at,device_id)
      values('goal-reward:'||p_run_id||':'||v_student,v_owner,v_student,v_goal.teaching_id,v_goal.session_id,v_goal.date,'participation',v_goal.reward_points,
        'مكافأة هدف الصف','class-goal:'||v_goal.id||':'||v_goal.run_id,p_client_updated_at,p_device_id)
      on conflict(owner_id,id) do nothing;
    end loop;
    update rakeezx.class_goals set state='completed',completed_at=v_now,reward_operation_id=p_run_id,
      client_updated_at=p_client_updated_at,device_id=p_device_id where owner_id=v_owner and id=v_goal.id returning * into v_goal;
  elsif v_goal.state<>'completed' then
    raise exception using errcode='22023',message='Goal is not active';
  end if;
  select coalesce(jsonb_agg(to_jsonb(l) order by l.id),'[]'::jsonb) into v_logs from rakeezx.logs l
    where l.owner_id=v_owner and l.note='class-goal:'||v_goal.id||':'||v_goal.run_id and l.deleted_at is null;
  v_result:=jsonb_build_object('mutationId',p_mutation_id,'outcome','completed','goal',to_jsonb(v_goal),'logs',v_logs);
  insert into rakeezx.sync_mutation_receipts(owner_id,mutation_id,entity,record_id,device_id,base_revision,operation,
    client_updated_at,request_patch,request_envelope,outcome,applied_groups,conflicted_groups,result_revision,canonical,result)
  values(v_owner,p_mutation_id,'class_goals',p_goal_id,p_device_id,v_goal.revision,'goal_reward',p_client_updated_at,
    '{}'::jsonb,v_envelope,'completed',array['goal'],array[]::text[],v_goal.revision,to_jsonb(v_goal),v_result);
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION rakeezx.apply_sync_v2_closed_term_report_command_before_student_0029(p_mutation_id text, p_device_id text, p_command text, p_term_id text, p_report_id text, p_supersedes_id text DEFAULT NULL::text, p_source_manifest jsonb DEFAULT '[]'::jsonb, p_payload jsonb DEFAULT '{}'::jsonb, p_client_updated_at bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid := auth.uid();
  v_receipt rakeezx.sync_mutation_receipts%rowtype;
  v_term rakeezx.terms%rowtype;
  v_report rakeezx.closed_term_reports%rowtype;
  v_previous rakeezx.closed_term_reports%rowtype;
  v_version integer;
  v_teaching_ids jsonb;
  v_payload_teaching_ids jsonb;
  v_normalized_manifest jsonb;
  v_envelope jsonb;
  v_result jsonb;
begin
  if v_owner is null then raise exception using errcode = '42501', message = 'Authentication required'; end if;
  if coalesce(p_mutation_id,'') = '' or char_length(p_mutation_id) > 200 or
     coalesce(p_device_id,'') = '' or char_length(p_device_id) > 200 or
     coalesce(p_term_id,'') = '' or coalesce(p_report_id,'') = '' or
     p_command not in ('close','correct') or
     p_source_manifest is null or pg_catalog.jsonb_typeof(p_source_manifest) <> 'array' or
     p_payload is null or pg_catalog.jsonb_typeof(p_payload) <> 'object' then
    raise exception using errcode = '22023', message = 'Invalid closed-term report command';
  end if;

  v_envelope := pg_catalog.jsonb_build_object(
    'mutationId',p_mutation_id,'deviceId',p_device_id,'command',p_command,'termId',p_term_id,
    'reportId',p_report_id,'supersedesId',p_supersedes_id,'sourceManifest',p_source_manifest,
    'payload',p_payload,'clientUpdatedAt',p_client_updated_at
  );
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text||':sync-v2:'||p_mutation_id,0));
  select * into v_receipt from rakeezx.sync_mutation_receipts
    where owner_id = v_owner and mutation_id = p_mutation_id;
  if found then
    if v_receipt.request_envelope is distinct from v_envelope then
      raise exception using errcode = '22023', message = 'Mutation ID was reused with a different request';
    end if;
    return v_receipt.result;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text||':closed-term:'||p_term_id,0));
  select * into v_term from rakeezx.terms where owner_id = v_owner and id = p_term_id for update;
  if not found or v_term.deleted_at is not null then raise exception using errcode = '22023', message = 'Term is unavailable'; end if;

  if p_command = 'close' then
    if v_term.status = 'closed' then raise exception using errcode = '22023', message = 'Legacy closed term cannot be backfilled automatically'; end if;
    if p_supersedes_id is not null or exists(select 1 from rakeezx.closed_term_reports where owner_id=v_owner and term_id=p_term_id) then
      raise exception using errcode = '22023', message = 'Closed-term report set already exists';
    end if;
    v_version := 1;
  else
    if v_term.status <> 'closed' or p_supersedes_id is null then
      raise exception using errcode = '22023', message = 'Correction requires a closed term and prior version';
    end if;
    select * into v_previous from rakeezx.closed_term_reports
      where owner_id=v_owner and id=p_supersedes_id and term_id=p_term_id and state='complete';
    if not found or exists(select 1 from rakeezx.closed_term_reports where owner_id=v_owner and supersedes_id=p_supersedes_id) then
      raise exception using errcode = '22023', message = 'Correction must supersede the current retained version';
    end if;
    if exists(select 1 from rakeezx.closed_term_reports newer where newer.owner_id=v_owner and newer.term_id=p_term_id and newer.version>v_previous.version) then
      raise exception using errcode = '22023', message = 'Correction must supersede the latest version';
    end if;
    v_version := v_previous.version + 1;
  end if;

  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object('entity',entry->>'entity','id',entry->>'id','revision',(entry->>'revision')::bigint)
    order by entry->>'entity',entry->>'id'
  ),'[]'::jsonb) into v_normalized_manifest
  from pg_catalog.jsonb_array_elements(p_source_manifest) entry
  where pg_catalog.jsonb_typeof(entry)='object' and entry ?& array['entity','id','revision'];
  if pg_catalog.jsonb_array_length(v_normalized_manifest) <> pg_catalog.jsonb_array_length(p_source_manifest) or
     rakeezx.closed_term_source_manifest(v_owner,p_term_id) is distinct from v_normalized_manifest then
    v_result := pg_catalog.jsonb_build_object('mutationId',p_mutation_id,'command',p_command,
      'outcome','rejected_source_changed','term',pg_catalog.to_jsonb(v_term));
    insert into rakeezx.sync_mutation_receipts(owner_id,mutation_id,entity,record_id,device_id,base_revision,operation,
      client_updated_at,request_patch,request_envelope,outcome,applied_groups,conflicted_groups,result)
    values(v_owner,p_mutation_id,'closed_term_reports',p_report_id,p_device_id,v_term.revision,'close_term_report',
      p_client_updated_at,'{}'::jsonb,v_envelope,'rejected_source_changed',array[]::text[],array['snapshot']::text[],v_result);
    return v_result;
  end if;
  if coalesce((p_payload->>'schemaVersion')::integer,0) <> 1 or p_payload#>>'{identity,term,id}' is distinct from p_term_id or
     pg_catalog.jsonb_typeof(p_payload->'teachingDocuments') <> 'array' or
     pg_catalog.jsonb_typeof(p_payload->'executionDocument') <> 'object' then
    raise exception using errcode = '22023', message = 'Closed-term report payload is incomplete';
  end if;
  select coalesce(pg_catalog.jsonb_agg(id order by id),'[]'::jsonb) into v_teaching_ids
    from rakeezx.teachings where owner_id=v_owner and term_id=p_term_id and deleted_at is null;
  select coalesce(pg_catalog.jsonb_agg(id order by id),'[]'::jsonb) into v_payload_teaching_ids
    from (select document#>>'{teaching,id}' id from pg_catalog.jsonb_array_elements(p_payload->'teachingDocuments') document) payload_ids;
  if v_payload_teaching_ids is distinct from v_teaching_ids then
    raise exception using errcode = '22023', message = 'Closed-term report teaching set is incomplete';
  end if;

  if p_command = 'close' then
    perform pg_catalog.set_config('rakeezx.closed_term_report_write','on',true);
    update rakeezx.terms set status='closed',client_updated_at=p_client_updated_at,device_id=p_device_id
      where owner_id=v_owner and id=p_term_id returning * into v_term;
  end if;
  insert into rakeezx.closed_term_reports(owner_id,id,term_id,year_id,version,supersedes_id,source_manifest,payload,
    state,client_updated_at,device_id)
  values(v_owner,p_report_id,p_term_id,v_term.year_id,v_version,p_supersedes_id,p_source_manifest,p_payload,
    'complete',p_client_updated_at,p_device_id)
  returning * into v_report;

  v_result := pg_catalog.jsonb_build_object('mutationId',p_mutation_id,'command',p_command,'outcome','complete',
    'report',pg_catalog.to_jsonb(v_report),'term',pg_catalog.to_jsonb(v_term));
  insert into rakeezx.sync_mutation_receipts(owner_id,mutation_id,entity,record_id,device_id,base_revision,operation,
    client_updated_at,request_patch,request_envelope,outcome,applied_groups,conflicted_groups,result_revision,canonical,result)
  values(v_owner,p_mutation_id,'closed_term_reports',p_report_id,p_device_id,v_term.revision,'close_term_report',
    p_client_updated_at,'{}'::jsonb,v_envelope,'complete',array['snapshot']::text[],array[]::text[],1,
    pg_catalog.to_jsonb(v_report),v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.apply_sync_v2_enrollment_command(p_mutation_id text, p_device_id text, p_command text, p_payload jsonb, p_client_updated_at bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_e rakeezx.enrollments%rowtype; v_receipt jsonb;
begin
  if auth.uid() is null then raise exception using errcode='42501',message='Authentication required'; end if;
  perform rakeezx.lock_student_lifecycle(auth.uid());
  if p_command='withdraw' and not exists(select 1 from rakeezx.sync_mutation_receipts where owner_id=auth.uid() and mutation_id=p_mutation_id) then
    select * into v_e from rakeezx.enrollments where owner_id=auth.uid() and id=p_payload->>'sourceEnrollmentId'
      and student_id=p_payload->>'studentId' and status='active' and deleted_at is null;
    if not found then raise exception using errcode='22023',message='STALE_SOURCE_ENROLLMENT'; end if;
  end if;
  return rakeezx.apply_sync_v2_enrollment_command_before_student_0029(p_mutation_id,p_device_id,p_command,p_payload,p_client_updated_at);
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.apply_sync_v2_enrollment_command_before_student_0029(p_mutation_id text, p_device_id text, p_command text, p_payload jsonb, p_client_updated_at bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid := auth.uid();
  v_student_id text := p_payload ->> 'studentId';
  v_source_id text := p_payload ->> 'sourceEnrollmentId';
  v_destination_id text := p_payload ->> 'destinationEnrollmentId';
  v_destination_section_id text := p_payload ->> 'destinationSectionId';
  v_date date := nullif(p_payload ->> 'date', '')::date;
  v_note text := coalesce(p_payload ->> 'note', '');
  v_receipt rakeezx.sync_mutation_receipts%rowtype;
  v_enrollment rakeezx.enrollments%rowtype;
  v_destination rakeezx.enrollments%rowtype;
  v_source_section text;
  v_sections text[];
  v_row jsonb;
  v_result jsonb;
  v_enrollments jsonb;
  v_roster_plan jsonb;
  v_outcome text;
  v_envelope jsonb;
begin
  if v_owner is null then raise exception using errcode = '42501', message = 'Authentication required'; end if;
  if coalesce(p_mutation_id, '') = '' or coalesce(p_device_id, '') = '' or
      p_command not in ('enroll', 'transfer', 'withdraw') or
      pg_catalog.jsonb_typeof(p_payload) <> 'object' or coalesce(v_student_id, '') = '' then
    raise exception using errcode = '22023', message = 'Invalid Sync V2 enrollment command';
  end if;
  v_envelope := pg_catalog.jsonb_build_object(
    'mutationId', p_mutation_id, 'deviceId', p_device_id, 'command', p_command,
    'payload', p_payload, 'clientUpdatedAt', p_client_updated_at
  );
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text || ':sync-v2:' || p_mutation_id, 0));
  select * into v_receipt from rakeezx.sync_mutation_receipts
    where owner_id = v_owner and mutation_id = p_mutation_id;
  if found then
    if v_receipt.request_envelope is distinct from v_envelope then
      raise exception using errcode = '22023', message = 'Mutation ID was reused with a different request';
    end if;
    return v_receipt.result;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text || ':student:' || v_student_id, 0));
  perform 1 from rakeezx.students where owner_id = v_owner and id = v_student_id and deleted_at is null for update;
  if not found then raise exception using errcode = 'P0001', message = 'Student is not active for current user'; end if;

  if p_command = 'transfer' then
    if coalesce(v_source_id, '') = '' or coalesce(v_destination_id, '') = '' or
        coalesce(v_destination_section_id, '') = '' or v_source_id = v_destination_id or v_date is null then
      raise exception using errcode = '22023', message = 'Invalid transfer command payload';
    end if;
    select * into v_enrollment from rakeezx.enrollments where owner_id = v_owner and id = v_source_id for update;
    select * into v_destination from rakeezx.enrollments where owner_id = v_owner and student_id = v_student_id
      and section_id = v_destination_section_id for update;
    if found and v_destination.id <> v_destination_id then v_destination_id := v_destination.id; end if;
    if v_enrollment.id is null or v_enrollment.student_id <> v_student_id or v_enrollment.status <> 'active' or v_enrollment.deleted_at is not null then
      select * into v_destination from rakeezx.enrollments where owner_id = v_owner and student_id = v_student_id
        and status = 'active' and deleted_at is null for update;
      if found and v_destination.section_id = v_destination_section_id then
        v_outcome := 'already_applied';
      else
        v_outcome := 'conflict';
      end if;
    else
      v_source_section := v_enrollment.section_id;
      if v_source_section = v_destination_section_id then v_outcome := 'already_applied';
      else
        perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text || ':section:' || least(v_source_section, v_destination_section_id), 0));
        perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text || ':section:' || greatest(v_source_section, v_destination_section_id), 0));
        perform 1 from rakeezx.sections where owner_id = v_owner and id = v_destination_section_id and deleted_at is null for update;
        if not found then raise exception using errcode = 'P0001', message = 'Destination section is not active'; end if;
        if exists (select 1 from rakeezx.enrollments where owner_id = v_owner and student_id = v_student_id
          and status = 'active' and deleted_at is null and id <> v_source_id) then
          raise exception using errcode = 'P0001', message = 'Another active enrollment already exists';
        end if;
        update rakeezx.enrollments set status = 'transferred', end_date = v_date, transfer_note = v_note,
          client_updated_at = p_client_updated_at, device_id = p_device_id where owner_id = v_owner and id = v_source_id;
        if v_destination.id is null then
          insert into rakeezx.enrollments (owner_id, id, student_id, section_id, roll_no, start_date, status, transfer_note, client_updated_at, device_id)
          values (v_owner, v_destination_id, v_student_id, v_destination_section_id, null, v_date, 'active', '', p_client_updated_at, p_device_id);
        elsif v_destination.deleted_at is not null then
          raise exception using errcode = 'P0001', message = 'Enrollment tombstone cannot be reactivated';
        else
          update rakeezx.enrollments set status = 'active', start_date = v_date, end_date = null, roll_no = null,
            client_updated_at = p_client_updated_at, device_id = p_device_id where owner_id = v_owner and id = v_destination.id;
        end if;
        v_outcome := 'applied';
      end if;
    end if;
    v_sections := array_remove(array[v_source_section, v_destination_section_id], null);
  elsif p_command = 'enroll' then
    if coalesce(v_destination_id, '') = '' or coalesce(v_destination_section_id, '') = '' or v_date is null then
      raise exception using errcode = '22023', message = 'Invalid enroll command payload';
    end if;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text || ':section:' || v_destination_section_id, 0));
    perform 1 from rakeezx.sections where owner_id = v_owner and id = v_destination_section_id and deleted_at is null for update;
    if not found then raise exception using errcode = 'P0001', message = 'Destination section is not active'; end if;
    select * into v_enrollment from rakeezx.enrollments where owner_id = v_owner and student_id = v_student_id and status = 'active' and deleted_at is null for update;
    if found and v_enrollment.section_id <> v_destination_section_id then v_outcome := 'conflict';
    elsif found then v_outcome := 'already_applied'; v_destination_id := v_enrollment.id;
    else
      insert into rakeezx.enrollments (owner_id, id, student_id, section_id, roll_no, start_date, status, transfer_note, client_updated_at, device_id)
      values (v_owner, v_destination_id, v_student_id, v_destination_section_id, null, v_date, 'active', '', p_client_updated_at, p_device_id);
      v_outcome := 'applied';
    end if;
    v_sections := array[v_destination_section_id];
  else
    select * into v_enrollment from rakeezx.enrollments where owner_id = v_owner and student_id = v_student_id
      and status = 'active' and deleted_at is null for update;
    if not found then v_outcome := 'already_applied'; v_sections := array[]::text[];
    else
      v_source_section := v_enrollment.section_id;
      perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text || ':section:' || v_source_section, 0));
      update rakeezx.enrollments set status = 'withdrawn', end_date = coalesce(v_date, current_date), transfer_note = v_note,
        client_updated_at = p_client_updated_at, device_id = p_device_id where owner_id = v_owner and id = v_enrollment.id;
      update rakeezx.students set status = 'withdrawn', client_updated_at = p_client_updated_at, device_id = p_device_id
        where owner_id = v_owner and id = v_student_id;
      v_outcome := 'applied'; v_sections := array[v_source_section];
    end if;
  end if;

  -- Server-owned complete sequential rosters: clear first, then assign stable current-roll order.
  if cardinality(v_sections) > 0 and v_outcome = 'applied' then
    select coalesce(jsonb_agg(jsonb_build_object('id', id, 'roll_no', next_roll)), '[]'::jsonb) into v_roster_plan
      from (
        select id, row_number() over (partition by section_id order by roll_no nulls last, id) as next_roll
        from rakeezx.enrollments where owner_id = v_owner and section_id = any(v_sections)
          and status = 'active' and deleted_at is null
      ) planned;
    update rakeezx.enrollments set roll_no = null where owner_id = v_owner and section_id = any(v_sections)
      and status = 'active' and deleted_at is null;
    update rakeezx.enrollments e set roll_no = planned.roll_no, client_updated_at = p_client_updated_at, device_id = p_device_id
      from jsonb_to_recordset(v_roster_plan) as planned(id text, roll_no integer)
      where e.owner_id = v_owner and e.id = planned.id;
  end if;

  select coalesce(jsonb_agg(to_jsonb(e) order by e.section_id, e.roll_no nulls last, e.id), '[]'::jsonb) into v_enrollments
    from rakeezx.enrollments e where e.owner_id = v_owner and (e.student_id = v_student_id or e.section_id = any(v_sections));
  v_result := jsonb_build_object('mutationId', p_mutation_id, 'command', p_command, 'outcome', v_outcome,
    'canonicalEnrollmentId', v_destination_id, 'enrollments', v_enrollments);
  insert into rakeezx.sync_mutation_receipts (owner_id, mutation_id, entity, record_id, device_id, base_revision, operation,
    client_updated_at, request_patch, request_envelope, outcome, applied_groups, conflicted_groups, result_revision, canonical, result)
  values (v_owner, p_mutation_id, 'enrollments', v_student_id, p_device_id, 0, p_command, p_client_updated_at,
    p_payload, v_envelope, v_outcome, array[]::text[], case when v_outcome = 'conflict' then array['__membership__']::text[] else array[]::text[] end,
    null, null, v_result);
  return v_result;
end;
$function$

