CREATE OR REPLACE FUNCTION rakeezx.apply_sync_v2_lifecycle_command_before_section_archive_0021(p_mutation_id text, p_device_id text, p_command text, p_target_id text, p_client_updated_at bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid := auth.uid();
  v_receipt rakeezx.sync_mutation_receipts%rowtype;
  v_envelope jsonb;
  v_target jsonb;
  v_outcome text;
  v_result jsonb;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_prior_context text := pg_catalog.current_setting('rakeezx.score_domain_write',true);
begin
  if v_owner is null then raise exception using errcode = '42501', message = 'Authentication required'; end if;
  if coalesce(p_mutation_id, '') = '' or coalesce(p_device_id, '') = '' or coalesce(p_target_id, '') = '' or
      p_command not in ('delete_item', 'delete_teaching', 'delete_student', 'delete_class') then
    raise exception using errcode = '22023', message = 'Invalid Sync V2 lifecycle command';
  end if;
  v_envelope := jsonb_build_object('mutationId', p_mutation_id, 'deviceId', p_device_id,
    'command', p_command, 'targetId', p_target_id, 'clientUpdatedAt', p_client_updated_at);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text || ':sync-v2:' || p_mutation_id, 0));
  select * into v_receipt from rakeezx.sync_mutation_receipts where owner_id=v_owner and mutation_id=p_mutation_id;
  if found then
    if v_receipt.request_envelope is distinct from v_envelope then
      raise exception using errcode='22023', message='Mutation ID was reused with a different request';
    end if;
    return v_receipt.result;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text || ':lifecycle:' || p_command || ':' || p_target_id, 0));

  if p_command = 'delete_item' then
    select to_jsonb(t) into v_target from rakeezx.items t where t.owner_id=v_owner and t.id=p_target_id for update;
    if v_target is null or v_target->>'deleted_at' is not null then v_outcome := 'already_deleted';
    else
    perform pg_catalog.set_config('rakeezx.score_domain_write','on',true);
    -- Include completions of previously retired children; retain all history.
    update rakeezx.score_subitem_completions c
      set deleted_at=v_now,device_id=p_device_id,client_updated_at=p_client_updated_at
      where c.owner_id=v_owner and c.deleted_at is null and exists(
        select 1 from rakeezx.score_subitems d where d.owner_id=v_owner and d.id=c.subitem_id and d.item_id=p_target_id);
    update rakeezx.score_subitems set deleted_at=v_now,device_id=p_device_id,client_updated_at=p_client_updated_at
      where owner_id=v_owner and item_id=p_target_id and deleted_at is null;
    update rakeezx.scores set deleted_at=v_now,device_id=p_device_id,client_updated_at=p_client_updated_at
      where owner_id=v_owner and item_id=p_target_id and deleted_at is null;
    update rakeezx.items set deleted_at=v_now,device_id=p_device_id,client_updated_at=p_client_updated_at
      where owner_id=v_owner and id=p_target_id and deleted_at is null;
    -- Original revision/touch triggers stamp every changed domain row. Values,
    -- creation history and prior tombstones are never rewritten or revived.
    perform pg_catalog.set_config('rakeezx.score_domain_write',coalesce(v_prior_context,''),true);
      v_outcome := 'deleted';
    end if;
  elsif p_command = 'delete_teaching' then
    select to_jsonb(t) into v_target from rakeezx.teachings t where t.owner_id=v_owner and t.id=p_target_id for update;
    if v_target is null or v_target->>'deleted_at' is not null then v_outcome := 'already_deleted';
    else
      update rakeezx.scores set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at
        where owner_id=v_owner and item_id in (select id from rakeezx.items where owner_id=v_owner and teaching_id=p_target_id);
      update rakeezx.attendance set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at
        where owner_id=v_owner and session_id in (select id from rakeezx.sessions where owner_id=v_owner and teaching_id=p_target_id);
      update rakeezx.session_roster_snapshots set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at
        where owner_id=v_owner and session_id in (select id from rakeezx.sessions where owner_id=v_owner and teaching_id=p_target_id);
      update rakeezx.logs set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and teaching_id=p_target_id;
      update rakeezx.slots set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and teaching_id=p_target_id;
      update rakeezx.sessions set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and teaching_id=p_target_id;
      update rakeezx.items set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and teaching_id=p_target_id;
      update rakeezx.teachings set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and id=p_target_id;
      v_outcome := 'deleted';
    end if;
  elsif p_command = 'delete_student' then
    select to_jsonb(t) into v_target from rakeezx.students t where t.owner_id=v_owner and t.id=p_target_id for update;
    if v_target is null or v_target->>'deleted_at' is not null then v_outcome := 'already_deleted';
    else
      update rakeezx.enrollments set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and student_id=p_target_id;
      update rakeezx.scores set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and student_id=p_target_id;
      update rakeezx.attendance set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and student_id=p_target_id;
      update rakeezx.logs set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and student_id=p_target_id;
      update rakeezx.notes set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and student_id=p_target_id;
      update rakeezx.students set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and id=p_target_id;
      v_outcome := 'deleted';
    end if;
  else
    -- Preserve a student with any relationship outside the class. A true
    -- orphan follows the existing Product lifecycle and is tombstoned in this
    -- same transaction, so a stale device cannot revive only part of a class.
    select to_jsonb(t) into v_target from rakeezx.sections t where t.owner_id=v_owner and t.id=p_target_id for update;
    if v_target is null or v_target->>'deleted_at' is not null then v_outcome := 'already_deleted';
    else
      update rakeezx.scores set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and item_id in (
        select i.id from rakeezx.items i join rakeezx.teachings t on t.owner_id=i.owner_id and t.id=i.teaching_id where i.owner_id=v_owner and t.section_id=p_target_id);
      update rakeezx.attendance set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and session_id in (
        select s.id from rakeezx.sessions s join rakeezx.teachings t on t.owner_id=s.owner_id and t.id=s.teaching_id where s.owner_id=v_owner and t.section_id=p_target_id);
      update rakeezx.session_roster_snapshots set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and session_id in (
        select s.id from rakeezx.sessions s join rakeezx.teachings t on t.owner_id=s.owner_id and t.id=s.teaching_id where s.owner_id=v_owner and t.section_id=p_target_id);
      update rakeezx.notes set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and (teaching_id in (select id from rakeezx.teachings where owner_id=v_owner and section_id=p_target_id) or session_id in (select s.id from rakeezx.sessions s join rakeezx.teachings t on t.owner_id=s.owner_id and t.id=s.teaching_id where s.owner_id=v_owner and t.section_id=p_target_id));
      update rakeezx.logs set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and teaching_id in (select id from rakeezx.teachings where owner_id=v_owner and section_id=p_target_id);
      update rakeezx.slots set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and teaching_id in (select id from rakeezx.teachings where owner_id=v_owner and section_id=p_target_id);
      update rakeezx.sessions set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and teaching_id in (select id from rakeezx.teachings where owner_id=v_owner and section_id=p_target_id);
      update rakeezx.items set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and teaching_id in (select id from rakeezx.teachings where owner_id=v_owner and section_id=p_target_id);
      update rakeezx.teachings set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and section_id=p_target_id;
      update rakeezx.enrollments set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and section_id=p_target_id;
      update rakeezx.students u set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at
        where u.owner_id=v_owner
          and exists (select 1 from rakeezx.enrollments e where e.owner_id=v_owner and e.student_id=u.id and e.section_id=p_target_id)
          and not exists (select 1 from rakeezx.enrollments e where e.owner_id=v_owner and e.student_id=u.id and e.section_id<>p_target_id)
          and not exists (select 1 from rakeezx.notes n where n.owner_id=v_owner and n.student_id=u.id and n.deleted_at is null)
          and not exists (select 1 from rakeezx.scores sc where sc.owner_id=v_owner and sc.student_id=u.id and sc.deleted_at is null)
          and not exists (select 1 from rakeezx.attendance a where a.owner_id=v_owner and a.student_id=u.id and a.deleted_at is null)
          and not exists (select 1 from rakeezx.logs l where l.owner_id=v_owner and l.student_id=u.id and l.deleted_at is null);
      update rakeezx.sections set deleted_at=v_now, device_id=p_device_id, client_updated_at=p_client_updated_at where owner_id=v_owner and id=p_target_id;
      v_outcome := 'deleted';
    end if;
  end if;
  v_result := jsonb_build_object('mutationId',p_mutation_id,'command',p_command,'targetId',p_target_id,'outcome',v_outcome);
  insert into rakeezx.sync_mutation_receipts (owner_id,mutation_id,entity,record_id,device_id,base_revision,operation,client_updated_at,request_patch,request_envelope,outcome,applied_groups,conflicted_groups,result)
  values (v_owner,p_mutation_id,'lifecycle',p_target_id,p_device_id,0,'lifecycle',p_client_updated_at,'{}'::jsonb,v_envelope,v_outcome,array['__deleted__']::text[],array[]::text[],v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.apply_sync_v2_lifecycle_command_before_student_0029(p_mutation_id text, p_device_id text, p_command text, p_target_id text, p_client_updated_at bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid:=auth.uid(); v_reason text;
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  -- Let the existing implementation replay/validate an idempotency receipt
  -- before inspecting rows that the first successful delete already tombstoned.
  if exists(select 1 from rakeezx.sync_mutation_receipts where owner_id=v_owner and mutation_id=p_mutation_id) then
    return rakeezx.apply_sync_v2_lifecycle_command_before_section_archive_0021(
      p_mutation_id,p_device_id,p_command,p_target_id,p_client_updated_at);
  end if;
  if p_command='delete_class' then
    if not exists(select 1 from rakeezx.sections where owner_id=v_owner and id=p_target_id and deleted_at is null) then
      return rakeezx.apply_sync_v2_lifecycle_command_before_section_archive_0021(
        p_mutation_id,p_device_id,p_command,p_target_id,p_client_updated_at);
    end if;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text||':section-lifecycle:'||p_target_id,0));
    v_reason:=rakeezx.section_delete_blocker(v_owner,p_target_id);
  elsif p_command='delete_teaching' then
    if not exists(select 1 from rakeezx.teachings where owner_id=v_owner and id=p_target_id and deleted_at is null) then
      return rakeezx.apply_sync_v2_lifecycle_command_before_section_archive_0021(
        p_mutation_id,p_device_id,p_command,p_target_id,p_client_updated_at);
    end if;
    v_reason:=rakeezx.teaching_delete_blocker(v_owner,p_target_id);
  end if;
  if v_reason is not null then raise exception using errcode='22023',message='Retained records require archive',detail=v_reason; end if;
  if p_command in ('delete_class','delete_teaching') then
    perform pg_catalog.set_config('rakeezx.section_lifecycle_delete','on',true);
  end if;
  return rakeezx.apply_sync_v2_lifecycle_command_before_section_archive_0021(
    p_mutation_id,p_device_id,p_command,p_target_id,p_client_updated_at);
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.apply_sync_v2_mutation_before_student_0029(p_entity text, p_record_id text, p_mutation_id text, p_device_id text, p_base_revision bigint, p_patch jsonb DEFAULT '{}'::jsonb, p_operation text DEFAULT 'patch'::text, p_client_updated_at bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid := auth.uid();
  v_field_map jsonb := rakeezx.sync_v2_field_map(p_entity);
  v_receipt rakeezx.sync_mutation_receipts%rowtype;
  v_request_envelope jsonb;
  v_row jsonb;
  v_revision bigint;
  v_field_revisions jsonb;
  v_deleted_at timestamptz;
  v_field text;
  v_group text;
  v_requested_groups text[] := '{}'::text[];
  v_conflicted_groups text[] := '{}'::text[];
  v_applied_groups text[] := '{}'::text[];
  v_effective_patch jsonb := '{}'::jsonb;
  v_set_list text := '';
  v_column_list text := '';
  v_value_list text := '';
  v_sql text;
  v_outcome text;
  v_result jsonb;
  v_natural_key jsonb;
  v_identity_lock text;
  v_natural_lookup_sql text;
  v_canonicalized boolean := false;
  v_create_raced boolean := false;
begin
  if v_owner is null then
    raise exception using errcode = '42501', message = 'Authentication required';
  end if;
  if v_field_map is null then
    raise exception using errcode = '22023', message = 'Unknown sync entity';
  end if;
  if coalesce(p_record_id, '') = '' or coalesce(p_mutation_id, '') = '' or
      char_length(p_mutation_id) > 200 or coalesce(p_device_id, '') = '' or
      char_length(p_device_id) > 200 or p_base_revision is null or p_base_revision < 0 or
      p_operation is null or p_operation not in ('create','patch','delete') or
      p_patch is null or pg_catalog.jsonb_typeof(p_patch) <> 'object' then
    raise exception using errcode = '22023', message = 'Invalid sync mutation envelope';
  end if;
  if p_entity = 'profile' and p_record_id <> 'profile' then
    raise exception using errcode = '22023', message = 'Profile record identity must be profile';
  end if;
  if p_operation = 'delete' and p_patch <> '{}'::jsonb then
    raise exception using errcode = '22023', message = 'Delete mutation cannot include a field patch';
  end if;
  if p_operation = 'create' and p_base_revision <> 0 then
    raise exception using errcode = '22023', message = 'Create mutation base revision must be zero';
  end if;

  for v_field in select pg_catalog.jsonb_object_keys(p_patch)
  loop
    v_group := v_field_map ->> v_field;
    if v_group is null then
      raise exception using errcode = '22023', message = 'Field is not allowed for this sync entity: ' || v_field;
    end if;
    if not v_group = any(v_requested_groups) then
      v_requested_groups := pg_catalog.array_append(v_requested_groups, v_group);
    end if;
  end loop;

  v_request_envelope := pg_catalog.jsonb_build_object(
    'entity', p_entity,
    'recordId', p_record_id,
    'mutationId', p_mutation_id,
    'deviceId', p_device_id,
    'baseRevision', p_base_revision,
    'operation', p_operation,
    'patch', p_patch,
    'clientUpdatedAt', p_client_updated_at
  );

  -- A mutation-id lock closes the retry race before the receipt exists.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_owner::text || ':sync-v2:' || p_mutation_id, 0)
  );
  select * into v_receipt
  from rakeezx.sync_mutation_receipts
  where owner_id = v_owner and mutation_id = p_mutation_id;
  if found then
    if v_receipt.request_envelope is distinct from v_request_envelope then
      raise exception using errcode = '22023', message = 'Mutation ID was reused with a different request';
    end if;
    return v_receipt.result;
  end if;

  -- Competing creates serialize on the Product natural identity where one is
  -- defined, otherwise on the durable requested id. This is independent from
  -- mutationId so three or more devices converge on the same canonical row.
  if p_operation = 'create' then
    if p_entity <> 'profile' then
      v_natural_key := rakeezx.sync_v2_natural_key(p_entity, p_patch);
    end if;
    v_identity_lock := case
      when p_entity = 'profile' then 'profile'
      when v_natural_key is not null then 'natural:' || v_natural_key::text
      else 'id:' || p_record_id
    end;
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_owner::text || ':sync-v2-create:' || p_entity || ':' || v_identity_lock, 0)
    );
  end if;

  if p_entity = 'profile' then
    execute 'select pg_catalog.to_jsonb(t), t.revision, t.field_revisions, t.deleted_at
             from rakeezx.profile t where t.owner_id = $1 for update'
      into v_row, v_revision, v_field_revisions, v_deleted_at using v_owner;
  else
    v_sql := pg_catalog.format(
      'select pg_catalog.to_jsonb(t), t.revision, t.field_revisions, t.deleted_at
       from rakeezx.%I t where t.owner_id = $1 and t.id = $2 for update', p_entity
    );
    execute v_sql into v_row, v_revision, v_field_revisions, v_deleted_at using v_owner, p_record_id;
  end if;

  if v_row is null and p_operation = 'create' and v_natural_key is not null then
    v_natural_lookup_sql := pg_catalog.format(
      'select pg_catalog.to_jsonb(t), t.revision, t.field_revisions, t.deleted_at
       from rakeezx.%I t
       where t.owner_id = $1
         and rakeezx.sync_v2_natural_key($2, pg_catalog.to_jsonb(t)) = $3
         and (not $4 or t.deleted_at is null)
       order by (t.deleted_at is null) desc, t.created_at, t.id
       limit 1 for update', p_entity
    );
    execute v_natural_lookup_sql
      into v_row, v_revision, v_field_revisions, v_deleted_at
      using v_owner, p_entity, v_natural_key, rakeezx.sync_v2_natural_key_reusable_after_delete(p_entity);
    v_canonicalized := v_row is not null;
  end if;

  if v_row is null then
    if p_operation <> 'create' then
      v_outcome := 'not_found';
      v_conflicted_groups := array['__record__'];
    else
      for v_field in select pg_catalog.jsonb_object_keys(p_patch) order by 1
      loop
        v_column_list := v_column_list || pg_catalog.format(', %I', v_field);
        v_value_list := v_value_list || pg_catalog.format(', p.%I', v_field);
      end loop;
      begin
        if p_entity = 'profile' then
          v_sql := pg_catalog.format(
            'with inserted as (
               insert into rakeezx.%I (owner_id, device_id, client_updated_at%s)
               select $1, $2, $3%s from pg_catalog.jsonb_populate_record(null::rakeezx.%I, $4) p
               returning *
             ) select pg_catalog.to_jsonb(inserted) from inserted',
            p_entity, v_column_list, v_value_list, p_entity
          );
          execute v_sql into v_row using v_owner, p_device_id, p_client_updated_at, p_patch;
        else
          v_sql := pg_catalog.format(
            'with inserted as (
               insert into rakeezx.%I (owner_id, id, device_id, client_updated_at%s)
               select $1, $2, $3, $4%s from pg_catalog.jsonb_populate_record(null::rakeezx.%I, $5) p
               returning *
             ) select pg_catalog.to_jsonb(inserted) from inserted',
            p_entity, v_column_list, v_value_list, p_entity
          );
          execute v_sql into v_row using v_owner, p_record_id, p_device_id, p_client_updated_at, p_patch;
        end if;
      exception when unique_violation then
        if v_natural_lookup_sql is null then raise; end if;
        execute v_natural_lookup_sql
          into v_row, v_revision, v_field_revisions, v_deleted_at
          using v_owner, p_entity, v_natural_key, rakeezx.sync_v2_natural_key_reusable_after_delete(p_entity);
        if v_row is null then raise; end if;
        v_create_raced := true;
      end;

      if v_create_raced then
        v_canonicalized := true;
        if v_deleted_at is not null then
          v_outcome := 'tombstoned';
          v_conflicted_groups := array['__deleted__'];
        else
          v_outcome := 'canonicalized';
          v_conflicted_groups := array['__canonical__'];
        end if;
      else
        v_revision := (v_row ->> 'revision')::bigint;
        v_applied_groups := v_requested_groups;
        v_outcome := 'applied';
      end if;
    end if;
  else
    if p_base_revision > v_revision then
      raise exception using errcode = '22023', message = 'Mutation base revision is ahead of the server';
    end if;

    if v_canonicalized and v_deleted_at is not null then
      v_outcome := 'tombstoned';
      v_conflicted_groups := array['__deleted__'];
    elsif v_canonicalized then
      v_outcome := 'canonicalized';
      v_conflicted_groups := array['__canonical__'];
    elsif v_deleted_at is not null and p_operation <> 'delete' then
      v_outcome := 'tombstoned';
      v_conflicted_groups := array['__deleted__'];
    elsif p_operation = 'create' then
      v_outcome := 'conflict';
      v_conflicted_groups := array['__record__'];
    elsif p_operation = 'delete' then
      if v_deleted_at is null then
        if p_entity = 'profile' then
          execute 'with updated as (
                     update rakeezx.profile t
                     set deleted_at = pg_catalog.clock_timestamp(), device_id = $1, client_updated_at = $2
                     where t.owner_id = $3 returning *
                   ) select pg_catalog.to_jsonb(updated) from updated'
            into v_row using p_device_id, p_client_updated_at, v_owner;
        else
          v_sql := pg_catalog.format(
            'with updated as (
               update rakeezx.%I t
               set deleted_at = pg_catalog.clock_timestamp(), device_id = $1, client_updated_at = $2
               where t.owner_id = $3 and t.id = $4 returning *
             ) select pg_catalog.to_jsonb(updated) from updated', p_entity
          );
          execute v_sql into v_row using p_device_id, p_client_updated_at, v_owner, p_record_id;
        end if;
        v_revision := (v_row ->> 'revision')::bigint;
        v_applied_groups := array['__deleted__'];
        v_outcome := 'deleted';
      else
        v_outcome := 'already_deleted';
      end if;
    elsif p_entity in ('logs','session_roster_snapshots') then
      v_outcome := 'conflict';
      v_conflicted_groups := array['__immutable__'];
    else
      foreach v_group in array v_requested_groups
      loop
        if coalesce((v_field_revisions ->> v_group)::bigint, 1) > p_base_revision then
          v_conflicted_groups := pg_catalog.array_append(v_conflicted_groups, v_group);
        else
          v_applied_groups := pg_catalog.array_append(v_applied_groups, v_group);
        end if;
      end loop;

      for v_field in select pg_catalog.jsonb_object_keys(p_patch) order by 1
      loop
        v_group := v_field_map ->> v_field;
        if not v_group = any(v_conflicted_groups) then
          v_effective_patch := v_effective_patch || pg_catalog.jsonb_build_object(v_field, p_patch -> v_field);
          if v_set_list <> '' then v_set_list := v_set_list || ', '; end if;
          v_set_list := v_set_list || pg_catalog.format(
            '%I = (select p.%I from pg_catalog.jsonb_populate_record(null::rakeezx.%I, $1) p)',
            v_field, v_field, p_entity
          );
        end if;
      end loop;

      if v_effective_patch <> '{}'::jsonb then
        v_set_list := v_set_list || ', device_id = $2, client_updated_at = $3';
        if p_entity = 'profile' then
          v_sql := 'with updated as (
                      update rakeezx.profile t set ' || v_set_list || '
                      where t.owner_id = $4 returning *
                    ) select pg_catalog.to_jsonb(updated) from updated';
          execute v_sql into v_row using v_effective_patch, p_device_id, p_client_updated_at, v_owner;
        else
          v_sql := pg_catalog.format(
            'with updated as (
               update rakeezx.%I t set %s
               where t.owner_id = $4 and t.id = $5 returning *
             ) select pg_catalog.to_jsonb(updated) from updated', p_entity, v_set_list
          );
          execute v_sql into v_row using v_effective_patch, p_device_id, p_client_updated_at, v_owner, p_record_id;
        end if;
        v_revision := (v_row ->> 'revision')::bigint;
      end if;

      if pg_catalog.cardinality(v_conflicted_groups) = 0 then
        v_outcome := 'applied';
      elsif pg_catalog.cardinality(v_applied_groups) > 0 then
        v_outcome := 'applied_with_conflicts';
      else
        v_outcome := 'conflict';
      end if;
    end if;
  end if;

  v_result := pg_catalog.jsonb_build_object(
    'mutationId', p_mutation_id,
    'entity', p_entity,
    'recordId', p_record_id,
    'canonicalId', case when p_entity = 'profile' then 'profile' else v_row ->> 'id' end,
    'outcome', v_outcome,
    'appliedGroups', pg_catalog.to_jsonb(v_applied_groups),
    'conflictedGroups', pg_catalog.to_jsonb(v_conflicted_groups),
    'resultRevision', v_revision,
    'canonical', v_row
  );

  insert into rakeezx.sync_mutation_receipts (
    owner_id, mutation_id, entity, record_id, device_id, base_revision, operation,
    client_updated_at, request_patch, request_envelope, outcome, applied_groups, conflicted_groups,
    result_revision, canonical, result
  ) values (
    v_owner, p_mutation_id, p_entity, p_record_id, p_device_id, p_base_revision, p_operation,
    p_client_updated_at, p_patch, v_request_envelope, v_outcome, v_applied_groups, v_conflicted_groups,
    v_revision, v_row, v_result
  );

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.apply_sync_v2_section_lifecycle_command_before_student_0029(p_mutation_id text, p_device_id text, p_command text, p_section_id text, p_archive_date date DEFAULT NULL::date, p_client_updated_at bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid:=auth.uid(); v_receipt rakeezx.sync_mutation_receipts%rowtype; v_section rakeezx.sections%rowtype;
  v_envelope jsonb; v_result jsonb; v_outcome text; v_conflict boolean:=false; v_now timestamptz:=pg_catalog.clock_timestamp();
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  if coalesce(p_mutation_id,'')='' or coalesce(p_device_id,'')='' or coalesce(p_section_id,'')='' or
     p_command not in ('archive_class','reopen_class') or (p_command='archive_class' and p_archive_date is null) then
    raise exception using errcode='22023',message='Invalid section lifecycle command';
  end if;
  v_envelope:=jsonb_build_object('mutationId',p_mutation_id,'deviceId',p_device_id,'command',p_command,
    'sectionId',p_section_id,'archiveDate',p_archive_date,'clientUpdatedAt',p_client_updated_at);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text||':sync-v2:'||p_mutation_id,0));
  select * into v_receipt from rakeezx.sync_mutation_receipts where owner_id=v_owner and mutation_id=p_mutation_id;
  if found then
    if v_receipt.request_envelope is distinct from v_envelope then raise exception using errcode='22023',message='Mutation ID was reused with a different request'; end if;
    return v_receipt.result;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text||':section-lifecycle:'||p_section_id,0));
  select * into v_section from rakeezx.sections where owner_id=v_owner and id=p_section_id for update;
  if not found or v_section.deleted_at is not null then raise exception using errcode='22023',message='Section is unavailable'; end if;
  perform pg_catalog.set_config('rakeezx.section_lifecycle_write','on',true);
  if p_command='archive_class' then
    if v_section.status='archived' then v_outcome:='already_archived';
    else
      update rakeezx.sections set status='archived',archived_at=v_now,archive_date=p_archive_date,
        client_updated_at=p_client_updated_at,device_id=p_device_id where owner_id=v_owner and id=p_section_id returning * into v_section;
      v_outcome:='archived';
    end if;
  else
    if v_section.status='active' then v_outcome:='already_active';
    elsif v_section.archived_at is null or v_section.archive_date is null then v_outcome:='rejected_lifecycle';
    elsif not exists(select 1 from rakeezx.years y where y.owner_id=v_owner and y.id=v_section.year_id and y.deleted_at is null and y.status<>'archived') then v_outcome:='rejected_year';
    elsif not exists(select 1 from rakeezx.terms tm where tm.owner_id=v_owner and tm.year_id=v_section.year_id and tm.deleted_at is null and tm.status<>'closed') then v_outcome:='rejected_term';
    else
      perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        v_owner::text||':active-slot:'||locked.weekday::text||':'||locked.period::text,0))
      from (select distinct sl.weekday,sl.period from rakeezx.slots sl join rakeezx.teachings t
        on t.owner_id=sl.owner_id and t.id=sl.teaching_id
        where sl.owner_id=v_owner and t.section_id=p_section_id and sl.deleted_at is null and t.deleted_at is null
        order by sl.weekday,sl.period) locked;
      select exists(
        select 1 from rakeezx.slots own_slot
        join rakeezx.teachings own_t on own_t.owner_id=own_slot.owner_id and own_t.id=own_slot.teaching_id
        join rakeezx.slots other_slot on other_slot.owner_id=own_slot.owner_id and other_slot.weekday=own_slot.weekday and other_slot.period=own_slot.period and other_slot.deleted_at is null
        left join rakeezx.teachings other_t on other_t.owner_id=other_slot.owner_id and other_t.id=other_slot.teaching_id
        left join rakeezx.sections other_s on other_s.owner_id=other_t.owner_id and other_s.id=other_t.section_id
        where own_slot.owner_id=v_owner and own_t.section_id=p_section_id and own_slot.deleted_at is null and own_t.deleted_at is null
          and ((other_slot.kind in ('activity','waiting') and other_slot.term_id=own_t.term_id) or
            (other_slot.kind='teaching' and other_t.section_id<>p_section_id and other_t.deleted_at is null and other_s.deleted_at is null and other_s.status='active'))
      ) into v_conflict;
      if v_conflict then v_outcome:='rejected_slot_conflict';
      else
        update rakeezx.sections set status='active',archived_at=null,archive_date=null,
          client_updated_at=p_client_updated_at,device_id=p_device_id where owner_id=v_owner and id=p_section_id returning * into v_section;
        v_outcome:='reopened';
      end if;
    end if;
  end if;
  select * into v_section from rakeezx.sections where owner_id=v_owner and id=p_section_id;
  v_result:=jsonb_build_object('mutationId',p_mutation_id,'command',p_command,'outcome',v_outcome,'section',to_jsonb(v_section));
  insert into rakeezx.sync_mutation_receipts(owner_id,mutation_id,entity,record_id,device_id,base_revision,operation,
    client_updated_at,request_patch,request_envelope,outcome,applied_groups,conflicted_groups,result)
  values(v_owner,p_mutation_id,'sections',p_section_id,p_device_id,v_section.revision,'section_lifecycle',p_client_updated_at,
    '{}'::jsonb,v_envelope,v_outcome,case when v_outcome in ('archived','reopened') then array['lifecycle']::text[] else array[]::text[] end,
    case when v_outcome like 'rejected_%' then array['lifecycle']::text[] else array[]::text[] end,v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.apply_sync_v2_selected_attendance_command(p_mutation_id text, p_device_id text, p_session_id text, p_student_ids text[], p_status text, p_client_updated_at bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid := auth.uid();
  v_receipt rakeezx.sync_mutation_receipts%rowtype;
  v_session rakeezx.sessions%rowtype;
  v_teaching rakeezx.teachings%rowtype;
  v_snapshot rakeezx.session_roster_snapshots%rowtype;
  v_attendance rakeezx.attendance%rowtype;
  v_members jsonb;
  v_student text;
  v_envelope jsonb;
  v_result jsonb;
  v_rows jsonb := '[]';
  v_skipped jsonb := '[]';
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  if coalesce(btrim(p_mutation_id),'')='' or coalesce(btrim(p_device_id),'')='' or
    coalesce(btrim(p_session_id),'')='' or p_status is null or p_status not in ('present','late','excused','absent') or
    p_student_ids is null or array_ndims(p_student_ids) is distinct from 1 or
    cardinality(p_student_ids) not between 1 and 300 or
    exists(select 1 from unnest(p_student_ids) id where id is null or btrim(id)='' or length(id)>300) or
    (select count(distinct id) from unnest(p_student_ids) id) <> cardinality(p_student_ids)
  then raise exception using errcode='22023',message='Invalid selected attendance command'; end if;

  -- Same outer lifecycle mutex and inner mutation/session locks as current RPCs.
  perform rakeezx.lock_student_lifecycle(v_owner);
  v_envelope := jsonb_build_object('mode','selected','mutationId',p_mutation_id,'deviceId',p_device_id,
    'sessionId',p_session_id,'studentIds',to_jsonb(p_student_ids),'status',p_status,'clientUpdatedAt',p_client_updated_at);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text||':sync-v2:'||p_mutation_id,0));
  select * into v_receipt from rakeezx.sync_mutation_receipts where owner_id=v_owner and mutation_id=p_mutation_id;
  if found then
    if v_receipt.request_envelope is distinct from v_envelope then
      raise exception using errcode='22023',message='Mutation ID was reused with a different request';
    end if;
    return v_receipt.result;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text||':session-roster:'||p_session_id,0));
  select * into v_session from rakeezx.sessions where owner_id=v_owner and id=p_session_id and deleted_at is null for update;
  if not found or v_session.status in ('cancelled','cancelled_holiday') then
    raise exception using errcode='22023',message='Attendance session is unavailable';
  end if;
  select * into v_teaching from rakeezx.teachings where owner_id=v_owner and id=v_session.teaching_id and deleted_at is null for update;
  if not found then raise exception using errcode='22023',message='Attendance teaching is unavailable'; end if;
  select * into v_snapshot from rakeezx.session_roster_snapshots
    where owner_id=v_owner and session_id=p_session_id and deleted_at is null for update;
  if not found then
    if exists(select 1 from rakeezx.attendance where owner_id=v_owner and session_id=p_session_id and deleted_at is null) then
      raise exception using errcode='22023',message='Legacy session membership is unresolved';
    end if;
    select coalesce(jsonb_agg(jsonb_build_object('studentId',e.student_id,'rollNo',e.roll_no)
      order by e.roll_no nulls last,s.name,e.student_id),'[]'::jsonb) into v_members
      from rakeezx.enrollments e join rakeezx.students s on s.owner_id=e.owner_id and s.id=e.student_id and s.deleted_at is null
      where e.owner_id=v_owner and e.section_id=v_teaching.section_id and e.status='active' and e.deleted_at is null;
  else
    if v_snapshot.state <> 'complete' then raise exception using errcode='22023',message='Session roster is incomplete'; end if;
    v_members := v_snapshot.members;
  end if;
  -- Validate the ENTIRE batch before snapshot/attendance/receipt writes.
  foreach v_student in array p_student_ids loop
    perform 1 from rakeezx.students where owner_id=v_owner and id=v_student and deleted_at is null for update;
    if not found or not (v_members @> jsonb_build_array(jsonb_build_object('studentId',v_student))) then
      raise exception using errcode='22023',message='Student is outside the owned session roster';
    end if;
    perform 1 from rakeezx.enrollments where owner_id=v_owner and student_id=v_student and
      section_id=v_teaching.section_id and status='active' and deleted_at is null for update;
    if not found then raise exception using errcode='22023',message='Student enrollment is inactive'; end if;
  end loop;
  if v_snapshot.id is null then
    perform set_config('rakeezx.sync_v2_attendance_snapshot','on',true);
    insert into rakeezx.session_roster_snapshots(owner_id,id,session_id,teaching_id,section_id,captured_at,members,state,client_updated_at,device_id)
      values(v_owner,'srs:'||p_session_id,p_session_id,v_session.teaching_id,v_teaching.section_id,clock_timestamp(),v_members,'complete',p_client_updated_at,p_device_id)
      returning * into v_snapshot;
  end if;
  foreach v_student in array p_student_ids loop
    select * into v_attendance from rakeezx.attendance
      where owner_id=v_owner and session_id=p_session_id and student_id=v_student for update;
    if found then
      -- Includes tombstones: selected import is never a restore/edit operation.
      v_skipped := v_skipped||jsonb_build_array(to_jsonb(v_attendance));
    else
      insert into rakeezx.attendance(owner_id,id,student_id,session_id,teaching_id,date,status,note,client_updated_at,device_id)
        values(v_owner,'att:'||v_student||':'||p_session_id,v_student,p_session_id,v_session.teaching_id,v_session.date,p_status,'',p_client_updated_at,p_device_id)
        returning * into v_attendance;
      v_rows := v_rows||jsonb_build_array(to_jsonb(v_attendance));
    end if;
  end loop;
  if v_session.status='scheduled' and jsonb_array_length(v_rows)>0 then
    update rakeezx.sessions set status='held',client_updated_at=p_client_updated_at,device_id=p_device_id where owner_id=v_owner and id=p_session_id;
  end if;
  v_result := jsonb_build_object('mutationId',p_mutation_id,'outcome','applied','snapshot',to_jsonb(v_snapshot),'applied',v_rows,'skipped',v_skipped);
  insert into rakeezx.sync_mutation_receipts(owner_id,mutation_id,entity,record_id,device_id,base_revision,operation,client_updated_at,request_patch,request_envelope,outcome,applied_groups,conflicted_groups,result)
    values(v_owner,p_mutation_id,'attendance',p_session_id,p_device_id,0,'fill_attendance',p_client_updated_at,
      jsonb_build_object('mode','selected','studentIds',to_jsonb(p_student_ids),'status',p_status),v_envelope,'applied',array['status']::text[],array[]::text[],v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.apply_sync_v2_session_delete_command_before_student_0029(p_mutation_id text, p_device_id text, p_session_id text, p_client_updated_at bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid:=auth.uid();
  v_receipt rakeezx.sync_mutation_receipts%rowtype;
  v_session rakeezx.sessions%rowtype;
  v_envelope jsonb;
  v_session_json jsonb;
  v_result jsonb;
  v_outcome text;
  v_reason text;
  v_applied text[]:='{}'::text[];
  v_conflicted text[]:='{}'::text[];
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  if coalesce(p_mutation_id,'')='' or char_length(p_mutation_id)>200 or
     coalesce(p_device_id,'')='' or char_length(p_device_id)>200 or
     coalesce(p_session_id,'')='' then
    raise exception using errcode='22023',message='Invalid session delete command';
  end if;

  v_envelope:=jsonb_build_object('mutationId',p_mutation_id,'deviceId',p_device_id,
    'sessionId',p_session_id,'clientUpdatedAt',p_client_updated_at);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text||':sync-v2:'||p_mutation_id,0));
  select * into v_receipt from rakeezx.sync_mutation_receipts
    where owner_id=v_owner and mutation_id=p_mutation_id;
  if found then
    if v_receipt.request_envelope is distinct from v_envelope then
      raise exception using errcode='22023',message='Mutation ID was reused with a different request';
    end if;
    return v_receipt.result;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text||':session-delete:'||p_session_id,0));
  select * into v_session from rakeezx.sessions
    where owner_id=v_owner and id=p_session_id for update;
  if not found then
    v_outcome:='not_found'; v_reason:='not_found'; v_conflicted:=array['__record__']::text[];
    v_session_json:=null;
  elsif v_session.deleted_at is not null then
    v_outcome:='already_deleted'; v_applied:=array['__deleted__']::text[];
    v_session_json:=to_jsonb(v_session);
  else
    v_reason:=rakeezx.session_delete_blocker(v_owner,p_session_id);
    if v_reason is not null then
      v_outcome:='protected'; v_conflicted:=array['__protected__']::text[];
      v_session_json:=to_jsonb(v_session);
    else
      update rakeezx.sessions set deleted_at=pg_catalog.clock_timestamp(),device_id=p_device_id,
        client_updated_at=p_client_updated_at
        where owner_id=v_owner and id=p_session_id returning * into v_session;
      v_outcome:='deleted'; v_applied:=array['__deleted__']::text[];
      v_session_json:=to_jsonb(v_session);
    end if;
  end if;

  v_result:=jsonb_build_object('mutationId',p_mutation_id,'command','delete_session',
    'sessionId',p_session_id,'outcome',v_outcome,'reason',v_reason,'session',v_session_json);
  insert into rakeezx.sync_mutation_receipts(
    owner_id,mutation_id,entity,record_id,device_id,base_revision,operation,client_updated_at,
    request_patch,request_envelope,outcome,applied_groups,conflicted_groups,result_revision,canonical,result
  ) values(
    v_owner,p_mutation_id,'sessions',p_session_id,p_device_id,0,'session_delete',p_client_updated_at,
    '{}'::jsonb,v_envelope,v_outcome,v_applied,v_conflicted,
    case when v_session_json is null then null else (v_session_json->>'revision')::bigint end,
    v_session_json,v_result
  );
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.apply_sync_v2_teaching_creation_command(p_mutation_id text, p_device_id text, p_teaching_id text, p_section_id text, p_subject_id text, p_term_id text, p_order integer, p_item_ids jsonb DEFAULT '[]'::jsonb, p_client_updated_at bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid := auth.uid(); v_receipt rakeezx.sync_mutation_receipts%rowtype;
  v_section rakeezx.sections%rowtype; v_teaching rakeezx.teachings%rowtype; v_envelope jsonb; v_result jsonb; v_items jsonb;
  v_defaults jsonb := '[
    {"name":"المشاركة والتفاعل","max":10,"auto":"participation","perPoint":1,"penalty":1},
    {"name":"الواجبات","max":10,"auto":null,"perPoint":1,"penalty":1},
    {"name":"الأنشطة والمشاريع","max":20,"auto":null,"perPoint":1,"penalty":1},
    {"name":"الاختبارات القصيرة","max":20,"auto":null,"perPoint":1,"penalty":1},
    {"name":"الاختبار النهائي","max":40,"auto":null,"perPoint":1,"penalty":1}
  ]'::jsonb;
  v_index integer; v_default jsonb; v_item_id text;
begin
  if v_owner is null then raise exception using errcode='42501', message='Authentication required'; end if;
  if coalesce(p_mutation_id,'')='' or coalesce(p_device_id,'')='' or coalesce(p_teaching_id,'')='' or
    coalesce(p_section_id,'')='' or coalesce(p_subject_id,'')='' or coalesce(p_term_id,'')='' or
    p_order is null or jsonb_typeof(p_item_ids) <> 'array' or jsonb_array_length(p_item_ids) <> 5 then
    raise exception using errcode='22023', message='Invalid Sync V2 teaching creation command';
  end if;
  perform rakeezx.lock_student_lifecycle(v_owner);
  v_envelope := jsonb_build_object('mutationId',p_mutation_id,'deviceId',p_device_id,'teachingId',p_teaching_id,
    'sectionId',p_section_id,'subjectId',p_subject_id,'termId',p_term_id,'order',p_order,'itemIds',p_item_ids,'clientUpdatedAt',p_client_updated_at);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text||':sync-v2:'||p_mutation_id,0));
  select * into v_receipt from rakeezx.sync_mutation_receipts where owner_id=v_owner and mutation_id=p_mutation_id;
  if found then if v_receipt.request_envelope is distinct from v_envelope then raise exception using errcode='22023',message='Mutation ID was reused with a different request'; end if; return v_receipt.result; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text||':teaching:'||p_section_id||':'||p_subject_id||':'||p_term_id,0));
  select * into v_section from rakeezx.sections where owner_id=v_owner and id=p_section_id and deleted_at is null for update;
  if not found then raise exception using errcode='22023',message='Teaching section is unavailable'; end if;
  if v_section.status<>'active' or not exists(select 1 from rakeezx.years where owner_id=v_owner and id=v_section.year_id and deleted_at is null and status<>'archived') then
    raise exception using errcode='22023',message='Teaching year or section is unavailable'; end if;
  perform 1 from rakeezx.subjects where owner_id=v_owner and id=p_subject_id and deleted_at is null for update;
  if not found then raise exception using errcode='22023',message='Teaching subject is unavailable'; end if;
  perform 1 from rakeezx.terms where owner_id=v_owner and id=p_term_id and year_id=v_section.year_id and status<>'closed' and deleted_at is null for update;
  if not found then raise exception using errcode='22023',message='Teaching term is unavailable'; end if;
  -- Receipt replay above is exact; a new command cannot name a retired identity.
  if exists(select 1 from rakeezx.teachings where owner_id=v_owner and id=p_teaching_id and deleted_at is not null) then
    raise exception using errcode='22023',message='Teaching tombstone cannot be recreated'; end if;
  if exists(select 1 from rakeezx.teachings where owner_id=v_owner and id=p_teaching_id and
    (section_id<>p_section_id or subject_id<>p_subject_id or term_id<>p_term_id)) then
    raise exception using errcode='22023',message='Teaching identity scope mismatch'; end if;
  select * into v_teaching from rakeezx.teachings where owner_id=v_owner and deleted_at is null and section_id=p_section_id and subject_id=p_subject_id and term_id=p_term_id for update;
  if not found then
    insert into rakeezx.teachings(owner_id,id,section_id,subject_id,term_id,"order",client_updated_at,device_id)
      values(v_owner,p_teaching_id,p_section_id,p_subject_id,p_term_id,p_order,p_client_updated_at,p_device_id) returning * into v_teaching;
  end if;
  for v_index in 0..4 loop
    v_default := v_defaults->v_index; v_item_id := p_item_ids->>v_index;
    if coalesce(v_item_id,'')='' then raise exception using errcode='22023',message='Invalid default item identity'; end if;
    if not exists (select 1 from rakeezx.items where owner_id=v_owner and teaching_id=v_teaching.id and "order"=v_index and deleted_at is null) then
      insert into rakeezx.items(owner_id,id,teaching_id,name,max,"order",auto,per_point,penalty,client_updated_at,device_id)
      values(v_owner,v_item_id,v_teaching.id,v_default->>'name',(v_default->>'max')::integer,v_index,
        v_default->>'auto',(v_default->>'perPoint')::integer,(v_default->>'penalty')::integer,p_client_updated_at,p_device_id);
    end if;
  end loop;
  select coalesce(jsonb_agg(to_jsonb(i) order by i."order"),'[]'::jsonb) into v_items from rakeezx.items i where owner_id=v_owner and teaching_id=v_teaching.id and deleted_at is null;
  v_result:=jsonb_build_object('mutationId',p_mutation_id,'outcome','applied','canonicalTeaching',to_jsonb(v_teaching),'items',v_items);
  insert into rakeezx.sync_mutation_receipts(owner_id,mutation_id,entity,record_id,device_id,base_revision,operation,client_updated_at,request_patch,request_envelope,outcome,applied_groups,conflicted_groups,result)
    values(v_owner,p_mutation_id,'teachings',p_teaching_id,p_device_id,0,'create_teaching',p_client_updated_at,'{}'::jsonb,v_envelope,'applied',array['__create__']::text[],array[]::text[],v_result);
  return v_result;
end; $function$

