          select $1,$2,$3%s from pg_catalog.jsonb_populate_record(null::rakeezx.profile,$4) p',v_columns,v_values);
        execute v_sql using v_owner,'restore:'||p_restore_id,(v_operation->>'clientUpdatedAt')::bigint,v_patch;
      else
        v_sql:=pg_catalog.format('insert into rakeezx.%I(owner_id,id,device_id,client_updated_at%s)
          select $1,$2,$3,$4%s from pg_catalog.jsonb_populate_record(null::rakeezx.%I,$5) p',
          v_entity,v_columns,v_values,v_entity);
        execute v_sql using v_owner,v_id,'restore:'||p_restore_id,
          (v_operation->>'clientUpdatedAt')::bigint,v_patch;
      end if;
      if v_action='create_deleted' then
        if v_entity='profile' then
          update rakeezx.profile set deleted_at=pg_catalog.clock_timestamp()
            where owner_id=v_owner;
        else
          execute pg_catalog.format('update rakeezx.%I set deleted_at=pg_catalog.clock_timestamp()
            where owner_id=$1 and id=$2',v_entity) using v_owner,v_id;
        end if;
      end if;
    elsif v_action='delete' then
      if v_entity='profile' then
        update rakeezx.profile set deleted_at=pg_catalog.clock_timestamp(),
          device_id='restore:'||p_restore_id where owner_id=v_owner;
      else
        execute pg_catalog.format('update rakeezx.%I set deleted_at=pg_catalog.clock_timestamp(),
          device_id=$1 where owner_id=$2 and id=$3',v_entity)
          using 'restore:'||p_restore_id,v_owner,v_id;
      end if;
    else
      for v_field in select pg_catalog.jsonb_object_keys(v_patch) order by 1 loop
        if v_sets<>'' then v_sets:=v_sets||','; end if;
        v_sets:=v_sets||pg_catalog.format('%I=(select p.%I from pg_catalog.jsonb_populate_record(null::rakeezx.%I,$1) p)',
          v_field,v_field,v_entity);
      end loop;
      if v_sets='' then continue; end if;
      v_sets:=v_sets||',device_id=$2,client_updated_at=$3';
      if v_entity='profile' then
        execute 'update rakeezx.profile set '||v_sets||' where owner_id=$4'
          using v_patch,'restore:'||p_restore_id,(v_operation->>'clientUpdatedAt')::bigint,v_owner;
      else
        execute pg_catalog.format('update rakeezx.%I set %s where owner_id=$4 and id=$5',v_entity,v_sets)
          using v_patch,'restore:'||p_restore_id,(v_operation->>'clientUpdatedAt')::bigint,v_owner,v_id;
      end if;
    end if;
  end loop;
  perform rakeezx.assert_score_provenance_consistent(v_owner);
  v_canonical:=rakeezx.sync_v2_backup_canonical_score_v2(v_owner);
  v_result:=pg_catalog.jsonb_build_object('restoreId',p_restore_id,'backupHash',p_backup_hash,
    'stageHash',p_expected_stage_hash,
    'receipt',pg_catalog.jsonb_build_object('restoreId',p_restore_id,'status','finalized'),
    'canonical',v_canonical);
  insert into rakeezx.sync_restore_receipts(owner_id,restore_id,backup_hash,stage_hash,result)
    values(v_owner,p_restore_id,p_backup_hash,p_expected_stage_hash,v_result);
  update rakeezx.sync_restore_stages set state='finalized',finalized_at=pg_catalog.clock_timestamp()
    where owner_id=v_owner and restore_id=p_restore_id;
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.n36_delete_subjectless_section(p_section_id text, p_year_id text, p_term_id text, p_expected_fingerprint text DEFAULT NULL::text, p_mutation_id text DEFAULT NULL::text, p_device_id text DEFAULT NULL::text, p_commit boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_owner uuid:=auth.uid(); v_section rakeezx.sections%rowtype;
 v_year rakeezx.years%rowtype; v_term rakeezx.terms%rowtype;
 v_receipt rakeezx.sync_mutation_receipts%rowtype;
 v_envelope jsonb; v_result jsonb; v_fingerprint text; v_ids text[];
 v_enrollments text[]; v_orphans text[]:='{}'::text[];
 v_scope text:='section'; v_now timestamptz:=pg_catalog.clock_timestamp();
begin
 if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
 if p_commit is null or coalesce(p_section_id,'')='' or coalesce(p_year_id,'')='' or coalesce(p_term_id,'')=''
 or greatest(char_length(p_section_id),char_length(p_year_id),char_length(p_term_id))>240 then
  raise exception using errcode='22023',message='Invalid N36 target'; end if;
 -- Same first lock as public lifecycle RPC wrappers and statement triggers.
 perform rakeezx.lock_student_lifecycle(v_owner);
 if p_commit then
  if coalesce(p_mutation_id,'')='' or coalesce(p_device_id,'')='' or coalesce(p_expected_fingerprint,'')=''
   or greatest(char_length(p_mutation_id),char_length(p_device_id))>200 or p_expected_fingerprint !~ '^[a-f0-9]{32}$' then
   raise exception using errcode='22023',message='Invalid N36 envelope'; end if;
  v_envelope:=pg_catalog.jsonb_build_object('protocol','N36_SECTION_DELETE_V1','sectionId',p_section_id,'yearId',p_year_id,
   'termId',p_term_id,'fingerprint',p_expected_fingerprint,'mutationId',p_mutation_id,'deviceId',p_device_id);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text||':sync-v2:'||p_mutation_id,0));
  select * into v_receipt from rakeezx.sync_mutation_receipts where owner_id=v_owner and mutation_id=p_mutation_id;
  if found then
   if v_receipt.request_envelope is distinct from v_envelope then raise exception using errcode='22023',message='Mutation ID reused'; end if;
   return v_receipt.result;
  end if;
 end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text||':section-lifecycle:'||p_section_id,0));
 select * into v_section from rakeezx.sections where owner_id=v_owner and id=p_section_id for update;
 if not found or v_section.deleted_at is not null or v_section.status<>'active' or v_section.year_id<>p_year_id then
  raise exception using errcode='22023',message='N36 scope stale'; end if;
 select * into v_year from rakeezx.years where owner_id=v_owner and id=p_year_id for share;
 if not found or v_year.deleted_at is not null or v_year.status<>'active' then raise exception using errcode='22023',message='N36 year unavailable'; end if;
 select * into v_term from rakeezx.terms where owner_id=v_owner and id=p_term_id and year_id=p_year_id for share;
 if not found or v_term.deleted_at is not null or v_term.status<>'active' then raise exception using errcode='22023',message='N36 term unavailable'; end if;
 if exists(select 1 from rakeezx.teachings where owner_id=v_owner and section_id=p_section_id and deleted_at is null) then
  raise exception using errcode='22023',message='N36 section has teaching'; end if;
 select coalesce(pg_catalog.array_agg(id order by id),'{}'::text[]) into v_ids from rakeezx.teachings where owner_id=v_owner and section_id=p_section_id;
 select coalesce(pg_catalog.array_agg(id order by id),'{}'::text[]) into v_enrollments from rakeezx.enrollments where owner_id=v_owner and section_id=p_section_id and deleted_at is null;
 select pg_catalog.md5(pg_catalog.jsonb_build_object('owner',v_owner,'section',pg_catalog.to_jsonb(v_section),'year',pg_catalog.to_jsonb(v_year),'term',pg_catalog.to_jsonb(v_term),
 'teachings',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(t) order by t.id),'[]'::jsonb) from rakeezx.teachings t where t.owner_id=v_owner and t.section_id=p_section_id),
 'enrollments',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(e) order by e.id),'[]'::jsonb) from rakeezx.enrollments e where e.owner_id=v_owner and e.section_id=p_section_id))::text) into v_fingerprint;
 if p_commit and p_expected_fingerprint<>v_fingerprint then raise exception using errcode='22023',message='N36 scope stale'; end if;
 v_result:=pg_catalog.jsonb_build_object('protocol','N36_SECTION_DELETE_V1','ownerId',v_owner,'sectionId',p_section_id,'yearId',p_year_id,'termId',p_term_id,
 'scope','section','selectedTeachingId',null,'teachingIds','[]'::jsonb,'cascadeTeachingIds',pg_catalog.to_jsonb(v_ids),'enrollmentIds',pg_catalog.to_jsonb(v_enrollments),'fingerprint',v_fingerprint);
 if not p_commit then return v_result; end if;
 -- Normal N77 descendant tombstones; preserve every pupil and immutable report.
  perform pg_catalog.set_config('rakeezx.section_lifecycle_delete','on',true);
  perform pg_catalog.set_config('rakeezx.score_domain_write','on',true);
  -- Descendants first. Every update and receipt shares this RPC transaction.
  update rakeezx.score_subitem_completions c set deleted_at=v_now,device_id=p_device_id
    where c.owner_id=v_owner and c.deleted_at is null and (
      c.subitem_id in (select si.id from rakeezx.score_subitems si join rakeezx.items i
        on i.owner_id=si.owner_id and i.id=si.item_id where si.owner_id=v_owner and i.teaching_id=any(v_ids))
      or c.student_id=any(v_orphans));
  update rakeezx.score_subitems si set deleted_at=v_now,device_id=p_device_id
    where si.owner_id=v_owner and si.deleted_at is null and si.item_id in
      (select id from rakeezx.items where owner_id=v_owner and teaching_id=any(v_ids));
  update rakeezx.scores s set deleted_at=v_now,device_id=p_device_id
    where s.owner_id=v_owner and s.deleted_at is null and (s.student_id=any(v_orphans) or s.item_id in
      (select id from rakeezx.items where owner_id=v_owner and teaching_id=any(v_ids)));
  update rakeezx.attendance a set deleted_at=v_now,device_id=p_device_id
    where a.owner_id=v_owner and a.deleted_at is null and (a.student_id=any(v_orphans) or
      a.teaching_id=any(v_ids) or a.session_id in
      (select id from rakeezx.sessions where owner_id=v_owner and teaching_id=any(v_ids)));
  update rakeezx.session_roster_snapshots s set deleted_at=v_now,device_id=p_device_id
    where s.owner_id=v_owner and s.deleted_at is null and (s.teaching_id=any(v_ids) or
      s.session_id in (select id from rakeezx.sessions where owner_id=v_owner and teaching_id=any(v_ids)) or
      (v_scope='section' and s.section_id=v_section.id));
  update rakeezx.logs l set deleted_at=v_now,device_id=p_device_id
    where l.owner_id=v_owner and l.deleted_at is null and (l.student_id=any(v_orphans) or
      l.teaching_id=any(v_ids) or l.session_id in
      (select id from rakeezx.sessions where owner_id=v_owner and teaching_id=any(v_ids)));
  update rakeezx.notes n set deleted_at=v_now,device_id=p_device_id
    where n.owner_id=v_owner and n.deleted_at is null and (n.student_id=any(v_orphans) or
      n.teaching_id=any(v_ids) or n.session_id in
      (select id from rakeezx.sessions where owner_id=v_owner and teaching_id=any(v_ids)));
  update rakeezx.class_goals set deleted_at=v_now,device_id=p_device_id
    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);
  update rakeezx.class_charter_selections set deleted_at=v_now,device_id=p_device_id
    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);
  update rakeezx.group_arrangements set deleted_at=v_now,device_id=p_device_id
    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);
  update rakeezx.class_rules set deleted_at=v_now,device_id=p_device_id
    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);
  update rakeezx.slots set deleted_at=v_now,device_id=p_device_id
    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);
  update rakeezx.sessions set deleted_at=v_now,device_id=p_device_id
    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);
  update rakeezx.items set deleted_at=v_now,device_id=p_device_id
    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);
  update rakeezx.teachings set deleted_at=v_now,device_id=p_device_id
    where owner_id=v_owner and deleted_at is null and id=any(v_ids);
  if true then
    update rakeezx.enrollments set deleted_at=v_now,device_id=p_device_id
      where owner_id=v_owner and deleted_at is null and section_id=v_section.id;
    update rakeezx.students set deleted_at=v_now,device_id=p_device_id
      where owner_id=v_owner and deleted_at is null and id=any(v_orphans);
    update rakeezx.sections set deleted_at=v_now,device_id=p_device_id
      where owner_id=v_owner and deleted_at is null and id=v_section.id;
  end if;

 v_result:=v_result||pg_catalog.jsonb_build_object('mutationId',p_mutation_id,'outcome','deleted','orphanStudentIds','[]'::jsonb);
 insert into rakeezx.sync_mutation_receipts(owner_id,mutation_id,entity,record_id,device_id,base_revision,operation,
 request_patch,request_envelope,outcome,applied_groups,conflicted_groups,result)
 values(v_owner,p_mutation_id,'lifecycle',p_section_id,p_device_id,v_section.revision,'lifecycle','{}'::jsonb,v_envelope,'deleted',array['__deleted__']::text[],'{}'::text[],v_result);
 return v_result;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.n77_delete_teaching(p_teaching_id text, p_expected_section_id text, p_expected_fingerprint text DEFAULT NULL::text, p_mutation_id text DEFAULT NULL::text, p_device_id text DEFAULT NULL::text, p_commit boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid := auth.uid();
  v_section rakeezx.sections%rowtype;
  v_teaching rakeezx.teachings%rowtype;
  v_ids text[];
  v_fingerprint text;
  v_scope text;
  v_orphans text[] := '{}'::text[];
  v_receipt rakeezx.sync_mutation_receipts%rowtype;
  v_envelope jsonb;
  v_result jsonb;
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  if coalesce(p_teaching_id,'')='' or coalesce(p_expected_section_id,'')='' or
      char_length(p_teaching_id)>240 or char_length(p_expected_section_id)>240 then
    raise exception using errcode='22023',message='Invalid N77 target';
  end if;
  if p_commit and (coalesce(p_mutation_id,'')='' or coalesce(p_device_id,'')='' or
      coalesce(p_expected_fingerprint,'')='' or char_length(p_mutation_id)>200 or char_length(p_device_id)>200) then
    raise exception using errcode='22023',message='Invalid N77 commit envelope';
  end if;
  if p_commit then
    v_envelope := pg_catalog.jsonb_build_object('teachingId',p_teaching_id,'sectionId',p_expected_section_id,
      'fingerprint',p_expected_fingerprint,'mutationId',p_mutation_id,'deviceId',p_device_id);
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text||':sync-v2:'||p_mutation_id,0));
    select * into v_receipt from rakeezx.sync_mutation_receipts
      where owner_id=v_owner and mutation_id=p_mutation_id;
    if found then
      if v_receipt.request_envelope is distinct from v_envelope then
        raise exception using errcode='22023',message='Mutation ID was reused with a different request';
      end if;
      return v_receipt.result;
    end if;
  end if;
  -- All N77 scope transitions serialize on the owner/Section row.
  select * into v_section from rakeezx.sections
    where owner_id=v_owner and id=p_expected_section_id for update;
  if not found or v_section.deleted_at is not null then
    raise exception using errcode='22023',message='N77 scope is stale';
  end if;
  select * into v_teaching from rakeezx.teachings
    where owner_id=v_owner and id=p_teaching_id and section_id=v_section.id for update;
  if not found or v_teaching.deleted_at is not null then
    raise exception using errcode='22023',message='N77 scope is stale';
  end if;
  select pg_catalog.array_agg(id order by id) into v_ids from rakeezx.teachings
    where owner_id=v_owner and section_id=v_section.id and deleted_at is null;
  if v_ids is null or not (p_teaching_id=any(v_ids)) then
    raise exception using errcode='22023',message='N77 scope is stale';
  end if;
  v_scope := case when pg_catalog.array_length(v_ids,1)>1 then 'teaching' else 'section' end;
  -- A changed sibling set, selected row or Section invalidates the shown confirmation.
  select pg_catalog.md5(v_owner::text||':'||v_section.id||':'||v_section.revision::text||':'||
    pg_catalog.string_agg(t.id||':'||t.revision::text,',' order by t.id)) into v_fingerprint
    from rakeezx.teachings t where t.owner_id=v_owner and t.section_id=v_section.id and t.deleted_at is null;
  if p_commit and p_expected_fingerprint<>v_fingerprint then
    raise exception using errcode='22023',message='N77 scope is stale';
  end if;
  if v_scope='teaching' then v_ids := array[p_teaching_id]; end if;
  v_result := pg_catalog.jsonb_build_object('ownerId',v_owner,'sectionId',v_section.id,
    'selectedTeachingId',p_teaching_id,'scope',v_scope,'teachingIds',pg_catalog.to_jsonb(v_ids),
    'fingerprint',v_fingerprint);
  if not p_commit then return v_result; end if;

  -- A final Section Delete also closes live descendants of historical Teaching
  -- tombstones created by older lifecycle code. The confirmation still names
  -- only the final active Teaching.
  if v_scope='section' then
    select pg_catalog.array_agg(id order by id) into v_ids from rakeezx.teachings
      where owner_id=v_owner and section_id=v_section.id;
  end if;
  v_result := v_result || pg_catalog.jsonb_build_object('cascadeTeachingIds',pg_catalog.to_jsonb(v_ids));

  -- Student identity is shared and local-only assignments/submissions are not
  -- visible to this server. Preserve every student identity; removing the
  -- Section enrollment makes an otherwise unreferenced student invisible in UX.

  perform pg_catalog.set_config('rakeezx.section_lifecycle_delete','on',true);
  perform pg_catalog.set_config('rakeezx.score_domain_write','on',true);
  -- Descendants first. Every update and receipt shares this RPC transaction.
  update rakeezx.score_subitem_completions c set deleted_at=v_now,device_id=p_device_id
    where c.owner_id=v_owner and c.deleted_at is null and (
      c.subitem_id in (select si.id from rakeezx.score_subitems si join rakeezx.items i
        on i.owner_id=si.owner_id and i.id=si.item_id where si.owner_id=v_owner and i.teaching_id=any(v_ids))
      or c.student_id=any(v_orphans));
  update rakeezx.score_subitems si set deleted_at=v_now,device_id=p_device_id
    where si.owner_id=v_owner and si.deleted_at is null and si.item_id in
      (select id from rakeezx.items where owner_id=v_owner and teaching_id=any(v_ids));
  update rakeezx.scores s set deleted_at=v_now,device_id=p_device_id
    where s.owner_id=v_owner and s.deleted_at is null and (s.student_id=any(v_orphans) or s.item_id in
      (select id from rakeezx.items where owner_id=v_owner and teaching_id=any(v_ids)));
  update rakeezx.attendance a set deleted_at=v_now,device_id=p_device_id
    where a.owner_id=v_owner and a.deleted_at is null and (a.student_id=any(v_orphans) or
      a.teaching_id=any(v_ids) or a.session_id in
      (select id from rakeezx.sessions where owner_id=v_owner and teaching_id=any(v_ids)));
  update rakeezx.session_roster_snapshots s set deleted_at=v_now,device_id=p_device_id
    where s.owner_id=v_owner and s.deleted_at is null and (s.teaching_id=any(v_ids) or
      s.session_id in (select id from rakeezx.sessions where owner_id=v_owner and teaching_id=any(v_ids)) or
      (v_scope='section' and s.section_id=v_section.id));
  update rakeezx.logs l set deleted_at=v_now,device_id=p_device_id
    where l.owner_id=v_owner and l.deleted_at is null and (l.student_id=any(v_orphans) or
      l.teaching_id=any(v_ids) or l.session_id in
      (select id from rakeezx.sessions where owner_id=v_owner and teaching_id=any(v_ids)));
  update rakeezx.notes n set deleted_at=v_now,device_id=p_device_id
    where n.owner_id=v_owner and n.deleted_at is null and (n.student_id=any(v_orphans) or
      n.teaching_id=any(v_ids) or n.session_id in
      (select id from rakeezx.sessions where owner_id=v_owner and teaching_id=any(v_ids)));
  update rakeezx.class_goals set deleted_at=v_now,device_id=p_device_id
    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);
  update rakeezx.class_charter_selections set deleted_at=v_now,device_id=p_device_id
    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);
  update rakeezx.group_arrangements set deleted_at=v_now,device_id=p_device_id
    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);
  update rakeezx.class_rules set deleted_at=v_now,device_id=p_device_id
    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);
  update rakeezx.slots set deleted_at=v_now,device_id=p_device_id
    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);
  update rakeezx.sessions set deleted_at=v_now,device_id=p_device_id
    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);
  update rakeezx.items set deleted_at=v_now,device_id=p_device_id
    where owner_id=v_owner and deleted_at is null and teaching_id=any(v_ids);
  update rakeezx.teachings set deleted_at=v_now,device_id=p_device_id
    where owner_id=v_owner and deleted_at is null and id=any(v_ids);
  if v_scope='section' then
    update rakeezx.enrollments set deleted_at=v_now,device_id=p_device_id
      where owner_id=v_owner and deleted_at is null and section_id=v_section.id;
    update rakeezx.students set deleted_at=v_now,device_id=p_device_id
      where owner_id=v_owner and deleted_at is null and id=any(v_orphans);
    update rakeezx.sections set deleted_at=v_now,device_id=p_device_id
      where owner_id=v_owner and deleted_at is null and id=v_section.id;
  end if;
  v_result := v_result || pg_catalog.jsonb_build_object('mutationId',p_mutation_id,
    'outcome','deleted','orphanStudentIds',pg_catalog.to_jsonb(v_orphans));
  insert into rakeezx.sync_mutation_receipts(owner_id,mutation_id,entity,record_id,device_id,
    base_revision,operation,request_patch,request_envelope,outcome,applied_groups,
    conflicted_groups,result)
  values(v_owner,p_mutation_id,'lifecycle',p_teaching_id,p_device_id,0,'lifecycle','{}'::jsonb,
    v_envelope,'deleted',array['__deleted__']::text[],array[]::text[],v_result);
  return v_result;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.commit_enrollment_transfer(p_source jsonb, p_destination jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_owner uuid := auth.uid();
  v_source_id text := p_source ->> 'id';
  v_destination_id text := p_destination ->> 'id';
  v_student_id text := p_source ->> 'student_id';
  v_source_section_id text := p_source ->> 'section_id';
  v_destination_section_id text := p_destination ->> 'section_id';
  v_source rakeezx.enrollments%rowtype;
  v_destination rakeezx.enrollments%rowtype;
  v_source_section rakeezx.sections%rowtype;
  v_destination_section rakeezx.sections%rowtype;
  v_source_found boolean := false;
  v_destination_found boolean := false;
  v_source_stamp bigint := nullif(p_source ->> 'client_updated_at', '')::bigint;
  v_destination_stamp bigint := nullif(p_destination ->> 'client_updated_at', '')::bigint;
  v_destination_roll integer := nullif(p_destination ->> 'roll_no', '')::integer;
begin perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(auth.uid()::text||':student-lifecycle-safety',0));
  if v_owner is null then
    raise exception using errcode = '42501', message = 'Authentication required';
  end if;
  if p_source is null or p_destination is null or
      coalesce(v_source_id, '') = '' or coalesce(v_destination_id, '') = '' or v_source_id = v_destination_id or
      v_student_id is null or v_student_id = '' or
      p_destination ->> 'student_id' is distinct from v_student_id or
      p_source ->> 'status' is distinct from 'transferred' or
      p_destination ->> 'status' is distinct from 'active' or
      coalesce(v_source_section_id, '') = '' or coalesce(v_destination_section_id, '') = '' or
      v_source_section_id = v_destination_section_id or
      v_source_stamp is null or v_destination_stamp is null or
      v_destination_roll is null or v_destination_roll not between 1 and 999 then
    raise exception using errcode = '22023', message = 'Invalid enrollment transfer payload';
  end if;

  -- Serializes competing transfer requests for one student without imposing a
  -- new global active-membership index on uninspected existing production data.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_owner::text || ':' || v_student_id, 0));
  -- The source may be historical, but it must still be a section owned by this
  -- caller.  The destination must be an active owned section before either
  -- enrollment row can be changed.
  select * into v_source_section from rakeezx.sections
    where owner_id = v_owner and id = v_source_section_id
    for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'Source section is not owned by current user';
  end if;
  select * into v_destination_section from rakeezx.sections
    where owner_id = v_owner and id = v_destination_section_id
    for update;
  if not found or v_destination_section.deleted_at is not null then
    raise exception using errcode = 'P0001', message = 'Destination section is not active for current user';
  end if;

  perform 1 from rakeezx.enrollments
    where owner_id = v_owner and student_id = v_student_id
    for update;

  select * into v_source from rakeezx.enrollments
    where owner_id = v_owner and id = v_source_id
    for update;
  v_source_found := found;
  select * into v_destination from rakeezx.enrollments
    where owner_id = v_owner and id = v_destination_id
    for update;
  v_destination_found := found;

  -- IDs are technical identities, not authority to rewrite any owned row.
  -- Existing rows must match every immutable transfer identity in the receipt.
  if (v_source_found and (
        v_source.owner_id is distinct from v_owner or
        v_source.id is distinct from v_source_id or
        v_source.student_id is distinct from v_student_id or
        v_source.section_id is distinct from v_source_section_id
      )) or
      (v_destination_found and (
        v_destination.owner_id is distinct from v_owner or
        v_destination.id is distinct from v_destination_id or
        v_destination.student_id is distinct from v_student_id or
        v_destination.section_id is distinct from v_destination_section_id
      )) then
    raise exception using errcode = 'P0001', message = 'Enrollment identity does not match transfer payload';
  end if;

  if (v_source_found and v_source.deleted_at is not null) or
      (v_destination_found and v_destination.deleted_at is not null) then
    raise exception using errcode = 'P0001', message = 'Enrollment tombstone cannot be reactivated';
  end if;
  if (v_source_found and coalesce(v_source.client_updated_at, 0) > v_source_stamp) or
      (v_destination_found and coalesce(v_destination.client_updated_at, 0) > v_destination_stamp) then
    raise exception using errcode = 'P0001', message = 'Enrollment transfer is stale';
  end if;
  if exists (
    select 1 from rakeezx.enrollments
      where owner_id = v_owner and student_id = v_student_id and deleted_at is null and status = 'active'
        and id not in (v_source_id, v_destination_id)
  ) then
    raise exception using errcode = 'P0001', message = 'Another active enrollment already exists';
  end if;
  if exists (
    select 1 from rakeezx.enrollments
      where owner_id = v_owner and student_id = v_student_id
        and section_id = p_destination ->> 'section_id' and id <> v_destination_id
  ) then
    raise exception using errcode = 'P0001', message = 'Destination enrollment identity conflict';
  end if;
  if exists (
    select 1 from rakeezx.enrollments
      where owner_id = v_owner and section_id = p_destination ->> 'section_id'
        and status = 'active' and deleted_at is null and roll_no = v_destination_roll
        and id not in (v_source_id, v_destination_id)
  ) then
    raise exception using errcode = '23505', message = 'Destination roll number is already active';
  end if;

  if v_source_found then
    update rakeezx.enrollments
      set status = 'transferred',
          end_date = nullif(p_source ->> 'end_date', '')::date,
          transfer_note = coalesce(p_source ->> 'transfer_note', ''),
          client_updated_at = v_source_stamp,
          device_id = p_source ->> 'device_id'
      where owner_id = v_owner and id = v_source_id
      returning * into v_source;
  else
    insert into rakeezx.enrollments (
      id, student_id, section_id, roll_no, start_date, end_date, status,
      transfer_note, client_updated_at, device_id
    ) values (
      v_source_id, v_student_id, p_source ->> 'section_id',
      nullif(p_source ->> 'roll_no', '')::integer,
      nullif(p_source ->> 'start_date', '')::date,
      nullif(p_source ->> 'end_date', '')::date,
      'transferred', coalesce(p_source ->> 'transfer_note', ''),
      v_source_stamp, p_source ->> 'device_id'
    ) returning * into v_source;
  end if;

  if v_destination_found then
    update rakeezx.enrollments
      set roll_no = v_destination_roll,
          start_date = nullif(p_destination ->> 'start_date', '')::date,
          end_date = null,
          status = 'active',
          client_updated_at = v_destination_stamp,
          device_id = p_destination ->> 'device_id'
      where owner_id = v_owner and id = v_destination_id
      returning * into v_destination;
  else
    insert into rakeezx.enrollments (
      id, student_id, section_id, roll_no, start_date, end_date, status,
      transfer_note, client_updated_at, device_id
    ) values (
      v_destination_id, v_student_id, p_destination ->> 'section_id',
      v_destination_roll, nullif(p_destination ->> 'start_date', '')::date,
      null, 'active', coalesce(p_destination ->> 'transfer_note', ''),
      v_destination_stamp, p_destination ->> 'device_id'
    ) returning * into v_destination;
  end if;

  return pg_catalog.jsonb_build_object(
    'source', pg_catalog.to_jsonb(v_source),
    'destination', pg_catalog.to_jsonb(v_destination)
  );
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.commit_enrollment_transfer_and_renumber(p_source jsonb, p_destination jsonb, p_source_roster jsonb, p_destination_roster jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_owner uuid := auth.uid();
  v_source_id text := p_source ->> 'id';
  v_destination_id text := p_destination ->> 'id';
  v_student_id text := p_source ->> 'student_id';
  v_source_section_id text := p_source ->> 'section_id';
  v_destination_section_id text := p_destination ->> 'section_id';
  v_source_stamp bigint := nullif(p_source ->> 'client_updated_at', '')::bigint;
  v_destination_stamp bigint := nullif(p_destination ->> 'client_updated_at', '')::bigint;
  v_destination_roll integer := nullif(p_destination ->> 'roll_no', '')::integer;
  v_source rakeezx.enrollments%rowtype;
  v_destination rakeezx.enrollments%rowtype;
  v_source_found boolean := false;
  v_destination_found boolean := false;
  v_source_plan_count integer;
  v_destination_plan_count integer;
  v_source_active_count integer;
  v_destination_active_count integer;
begin perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(auth.uid()::text||':student-lifecycle-safety',0));
  if v_owner is null then
    raise exception using errcode = '42501', message = 'Authentication required';
  end if;
  if pg_catalog.jsonb_typeof(p_source) <> 'object' or pg_catalog.jsonb_typeof(p_destination) <> 'object' or
      pg_catalog.jsonb_typeof(p_source_roster) <> 'array' or pg_catalog.jsonb_typeof(p_destination_roster) <> 'array' or
      coalesce(v_source_id, '') = '' or coalesce(v_destination_id, '') = '' or v_source_id = v_destination_id or
      coalesce(v_student_id, '') = '' or p_destination ->> 'student_id' is distinct from v_student_id or
      p_source ->> 'status' is distinct from 'transferred' or p_destination ->> 'status' is distinct from 'active' or
      coalesce(v_source_section_id, '') = '' or coalesce(v_destination_section_id, '') = '' or
      v_source_section_id = v_destination_section_id or v_source_stamp is null or v_destination_stamp is null or
      v_destination_roll is null or v_destination_roll not between 1 and 999 then
    raise exception using errcode = '22023', message = 'Invalid transfer-and-renumber payload';
  end if;

  -- Reject malformed plans before any membership row is changed.  NULL is not
  -- allowed as a final number; it is only an internal, transaction-local step.
  if exists (
    select 1 from pg_catalog.jsonb_array_elements(p_source_roster) as entry(value)
      where pg_catalog.jsonb_typeof(entry.value) is distinct from 'object'
        or coalesce(entry.value ->> 'id', '') = ''
        or pg_catalog.jsonb_typeof(entry.value -> 'roll_no') is distinct from 'number'
        or not ((entry.value ->> 'roll_no') ~ '^[1-9][0-9]{0,2}$')
        or pg_catalog.jsonb_typeof(entry.value -> 'client_updated_at') is distinct from 'number'
  ) or exists (
    select 1 from pg_catalog.jsonb_array_elements(p_destination_roster) as entry(value)
      where pg_catalog.jsonb_typeof(entry.value) is distinct from 'object'
        or coalesce(entry.value ->> 'id', '') = ''
        or pg_catalog.jsonb_typeof(entry.value -> 'roll_no') is distinct from 'number'
        or not ((entry.value ->> 'roll_no') ~ '^[1-9][0-9]{0,2}$')
        or pg_catalog.jsonb_typeof(entry.value -> 'client_updated_at') is distinct from 'number'
  ) then
    raise exception using errcode = '22023', message = 'Invalid final enrollment roster';
  end if;

  -- Serialize one student first, then the two sections in a deterministic
  -- order.  This prevents concurrent transfers/renumbers from interleaving.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_owner::text || ':' || v_student_id, 0));
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_owner::text || ':section:' || least(v_source_section_id, v_destination_section_id), 0));
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_owner::text || ':section:' || greatest(v_source_section_id, v_destination_section_id), 0));

  perform 1 from rakeezx.sections
    where owner_id = v_owner and id in (v_source_section_id, v_destination_section_id)
    order by id for update;
  if (select count(*) from rakeezx.sections
      where owner_id = v_owner and id in (v_source_section_id, v_destination_section_id)) <> 2 then
    raise exception using errcode = 'P0001', message = 'Transfer section is not owned by current user';
  end if;
  if exists (
    select 1 from rakeezx.sections
      where owner_id = v_owner and id = v_destination_section_id and deleted_at is not null
  ) then
    raise exception using errcode = 'P0001', message = 'Destination section is not active for current user';
  end if;

  -- Lock every membership whose state or final number this operation uses.
  perform 1 from rakeezx.enrollments
    where owner_id = v_owner and (student_id = v_student_id or section_id in (v_source_section_id, v_destination_section_id))
    order by section_id, id for update;

  select * into v_source from rakeezx.enrollments
    where owner_id = v_owner and id = v_source_id;
  v_source_found := found;
  select * into v_destination from rakeezx.enrollments
    where owner_id = v_owner and id = v_destination_id;
  v_destination_found := found;

  if (v_source_found and (
        v_source.student_id is distinct from v_student_id or v_source.section_id is distinct from v_source_section_id
      )) or (v_destination_found and (
        v_destination.student_id is distinct from v_student_id or v_destination.section_id is distinct from v_destination_section_id
      )) then
    raise exception using errcode = 'P0001', message = 'Enrollment identity does not match transfer payload';
  end if;
  if (v_source_found and v_source.deleted_at is not null) or (v_destination_found and v_destination.deleted_at is not null) then
    raise exception using errcode = 'P0001', message = 'Enrollment tombstone cannot be reactivated';
  end if;
  if (v_source_found and coalesce(v_source.client_updated_at, 0) > v_source_stamp) or
      (v_destination_found and coalesce(v_destination.client_updated_at, 0) > v_destination_stamp) then
    raise exception using errcode = 'P0001', message = 'Enrollment transfer is stale';
  end if;
  if exists (
    select 1 from rakeezx.enrollments
      where owner_id = v_owner and student_id = v_student_id and deleted_at is null and status = 'active'
        and id not in (v_source_id, v_destination_id)
  ) then
    raise exception using errcode = 'P0001', message = 'Another active enrollment already exists';
  end if;
  if exists (
    select 1 from rakeezx.enrollments
      where owner_id = v_owner and student_id = v_student_id and section_id = v_destination_section_id
        and id <> v_destination_id
  ) then
    raise exception using errcode = 'P0001', message = 'Destination enrollment identity conflict';
  end if;

  -- First commit membership with no active destination roll.  The final plans
  -- below own every active number, so no intermediate partial-index conflict
  -- can exist even when the student returns to a formerly occupied number.
  if v_source_found then
    update rakeezx.enrollments
      set status = 'transferred', end_date = nullif(p_source ->> 'end_date', '')::date,
          transfer_note = coalesce(p_source ->> 'transfer_note', ''),
          client_updated_at = v_source_stamp, device_id = p_source ->> 'device_id'
      where owner_id = v_owner and id = v_source_id
      returning * into v_source;
  else
    insert into rakeezx.enrollments (
      id, student_id, section_id, roll_no, start_date, end_date, status,
      transfer_note, client_updated_at, device_id
    ) values (
      v_source_id, v_student_id, v_source_section_id, nullif(p_source ->> 'roll_no', '')::integer,
      nullif(p_source ->> 'start_date', '')::date, nullif(p_source ->> 'end_date', '')::date,
      'transferred', coalesce(p_source ->> 'transfer_note', ''), v_source_stamp, p_source ->> 'device_id'
    ) returning * into v_source;
  end if;

  if v_destination_found then
    update rakeezx.enrollments
      set roll_no = null, start_date = nullif(p_destination ->> 'start_date', '')::date,
          end_date = null, status = 'active', client_updated_at = v_destination_stamp,
          device_id = p_destination ->> 'device_id'
      where owner_id = v_owner and id = v_destination_id
      returning * into v_destination;
  else
    insert into rakeezx.enrollments (
      id, student_id, section_id, roll_no, start_date, end_date, status,
      transfer_note, client_updated_at, device_id
    ) values (
      v_destination_id, v_student_id, v_destination_section_id, null,
      nullif(p_destination ->> 'start_date', '')::date, null, 'active',
      coalesce(p_destination ->> 'transfer_note', ''), v_destination_stamp, p_destination ->> 'device_id'
    ) returning * into v_destination;
  end if;

  select count(*) into v_source_plan_count from pg_catalog.jsonb_to_recordset(p_source_roster)
    as plan(id text, roll_no integer, client_updated_at bigint, device_id text);
  select count(*) into v_destination_plan_count from pg_catalog.jsonb_to_recordset(p_destination_roster)
    as plan(id text, roll_no integer, client_updated_at bigint, device_id text);
  select count(*) into v_source_active_count from rakeezx.enrollments
    where owner_id = v_owner and section_id = v_source_section_id and status = 'active' and deleted_at is null;
  select count(*) into v_destination_active_count from rakeezx.enrollments
    where owner_id = v_owner and section_id = v_destination_section_id and status = 'active' and deleted_at is null;

  if v_source_plan_count <> v_source_active_count or v_destination_plan_count <> v_destination_active_count then
    raise exception using errcode = 'P0001', message = 'Enrollment roster changed before transfer renumber';
  end if;
  if exists (
    select 1 from pg_catalog.jsonb_to_recordset(p_source_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)
      left join rakeezx.enrollments enrollment on enrollment.owner_id = v_owner and enrollment.id = plan.id
      where enrollment.id is null or enrollment.section_id <> v_source_section_id or enrollment.status <> 'active' or
        enrollment.deleted_at is not null or coalesce(enrollment.client_updated_at, 0) > plan.client_updated_at
  ) or exists (
    select 1 from pg_catalog.jsonb_to_recordset(p_destination_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)
      left join rakeezx.enrollments enrollment on enrollment.owner_id = v_owner and enrollment.id = plan.id
      where enrollment.id is null or enrollment.section_id <> v_destination_section_id or enrollment.status <> 'active' or
        enrollment.deleted_at is not null or coalesce(enrollment.client_updated_at, 0) > plan.client_updated_at
  ) or exists (
    select 1 from (select id from pg_catalog.jsonb_to_recordset(p_source_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)) ids group by id having count(*) > 1
  ) or exists (
    select 1 from (select id from pg_catalog.jsonb_to_recordset(p_destination_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)) ids group by id having count(*) > 1
  ) or exists (
    select 1 from (select roll_no from pg_catalog.jsonb_to_recordset(p_source_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)) rolls group by roll_no having count(*) > 1
  ) or exists (
    select 1 from (select roll_no from pg_catalog.jsonb_to_recordset(p_destination_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)) rolls group by roll_no having count(*) > 1
  ) or not exists (
    select 1 from pg_catalog.jsonb_to_recordset(p_destination_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)
      where plan.id = v_destination_id and plan.roll_no = v_destination_roll
  ) then
    raise exception using errcode = 'P0001', message = 'Invalid or stale final enrollment roster';
  end if;

  -- The partial unique index ignores NULL.  Both rosters are clear only
  -- inside this transaction, then receive their complete final sequences.
  update rakeezx.enrollments set roll_no = null
    where owner_id = v_owner and section_id in (v_source_section_id, v_destination_section_id)
      and status = 'active' and deleted_at is null;

  update rakeezx.enrollments enrollment
    set roll_no = plan.roll_no, client_updated_at = plan.client_updated_at, device_id = plan.device_id
    from pg_catalog.jsonb_to_recordset(p_source_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)
    where enrollment.owner_id = v_owner and enrollment.id = plan.id;
  update rakeezx.enrollments enrollment
    set roll_no = plan.roll_no, client_updated_at = plan.client_updated_at, device_id = plan.device_id
    from pg_catalog.jsonb_to_recordset(p_destination_roster)
      as plan(id text, roll_no integer, client_updated_at bigint, device_id text)
    where enrollment.owner_id = v_owner and enrollment.id = plan.id;

  select * into v_source from rakeezx.enrollments where owner_id = v_owner and id = v_source_id;
  select * into v_destination from rakeezx.enrollments where owner_id = v_owner and id = v_destination_id;
  return pg_catalog.jsonb_build_object(
    'source', pg_catalog.to_jsonb(v_source),
    'destination', pg_catalog.to_jsonb(v_destination),
    'source_roster', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(enrollment) order by enrollment.roll_no)
      from rakeezx.enrollments enrollment where owner_id = v_owner and section_id = v_source_section_id
        and status = 'active' and deleted_at is null), '[]'::jsonb),
    'destination_roster', coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(enrollment) order by enrollment.roll_no)
      from rakeezx.enrollments enrollment where owner_id = v_owner and section_id = v_destination_section_id
        and status = 'active' and deleted_at is null), '[]'::jsonb)
  );
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.provision_account_workspace(p_defaults jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid := auth.uid(); v_profile rakeezx.profile%rowtype;
  v_year jsonb; v_calendar jsonb; v_subject jsonb; v_row jsonb;
  v_hash text; v_manifest jsonb; v_preset text; v_expected jsonb; v_normalized jsonb; v_key text;
begin
  if v_owner is null then raise exception using errcode='42501', message='Authentication required'; end if;
  perform rakeezx.lock_student_lifecycle(v_owner);
  select * into v_profile from rakeezx.profile where owner_id=v_owner for update;
  if v_profile.owner_id is null or v_profile.provisioning_state not in ('PROVISIONING','READY') or
      v_profile.profile_status <> 'READY' then
    raise exception using errcode='42501', message='Account provisioning has not begun';
  end if;
  if v_profile.provisioning_state='READY' and
      rakeezx.account_provisioning_foundation_complete(v_owner) then
    return pg_catalog.jsonb_build_object('contract',rakeezx.account_contract(),
      'snapshot',rakeezx.account_provisioning_snapshot());
  end if;
  if not exists(select 1 from rakeezx.account_access_grants where owner_id=v_owner and
      grant_type='beta_full' and status='active' and (expires_at is null or expires_at > now())) then
    raise exception using errcode='42501', message='Beta access is required';
  end if;
  -- READY repair is kept behind the original immutable receipt/hash rules.
  -- Initial provisioning must never retag a previously committed foundation.
  if v_profile.provisioning_state='READY' then
    return rakeezx.provision_account_workspace_before_n117(p_defaults);
  end if;
